import java.nio.file.*;
import resforge.audio.OggVorbis;
byte[] b = Files.readAllBytes(Path.of("src/test/resources/resforge/audio/vorbis-sample.ogg"));
var pcm = OggVorbis.decode(b);
System.out.println("len="+pcm.data.length+" rate="+pcm.rate+" channels="+pcm.channels+" frames="+pcm.frames()+" secs="+pcm.seconds());
int min=32767,max=-32768; long sum=0; int nz=0;
for(int i=0;i+1<pcm.data.length;i+=2){ int v=(short)((pcm.data[i]&0xff)|((pcm.data[i+1]&0xff)<<8)); if(v<min)min=v;if(v>max)max=v;sum+=v;if(v!=0)nz++; }
System.out.println("min="+min+" max="+max+" mean="+(sum/(double)(pcm.data.length/2))+" nonzero="+nz);
System.out.println("first16="+java.util.HexFormat.of().formatHex(java.util.Arrays.copyOf(pcm.data,16)));
/exit
EOF"}

