{"command": "perl -e '
use strict; use warnings;
open my $f, "<:raw", "src/test/resources/resforge/audio/vorbis-sample.ogg" or die $!; local $/; my $b=<$f>;
my $p=0; my $i=0;
while($p+27 <= length($b) && substr($b,$p,4) eq "OggS") {
  my $n=ord(substr($b,$p+26,1)); my $segs=substr($b,$p+27,$n);
  my $body=0; $body+=ord($_) for split //,$segs;
  my $gran=unpack("q<", substr($b,$p+6,8)); my $serial=unpack("V",substr($b,$p+14,4));
  my $type=ord(substr($b,$p+5,1));
  printf "page %d offset=%d type=%d gran=%d serial=%u segs=%s body=%d end=%d\n",$i,$p,$type,$gran,$serial,join(",",map{ord}split//,$segs),$body,$p+27+$n+$body;
  $p += 27+$n+$body; $i++;
}
print "len=".length($b)." end=$p remaining=".(length($b)-$p)."\n";
'"}

