{"command": "jshell --class-path build-maven/classes:lib/jorbis-0.0.17.jar <<'EOF'
import java.nio.file.*; import java.util.*;
import resforge.audio.OggVorbis;
byte[] b=Files.readAllBytes(Path.of("src/test/resources/resforge/audio/vorbis-sample.ogg"));
void tryDecode(String name, byte[] x){ try { var p=OggVorbis.decode(x); System.out.println(name+": OK len="+p.data.length+" rate="+p.rate+" ch="+p.channels); } catch(Throwable t){ System.out.println(name+": "+t.getClass().getName()+": "+t.getMessage()); } }
tryDecode("full", b);
tryDecode("empty", new byte[0]);
tryDecode("random", new byte[]{1,2,3,4,5});
tryDecode("firstpage", Arrays.copyOfRange(b,0,58));
tryDecode("headers-only", Arrays.copyOfRange(b,0,3999));
tryDecode("half-first", Arrays.copyOfRange(b,0,30));
byte[] c=b.clone(); c[28]=(byte)2; tryDecode("bad-id-packet-type",c);
byte[] d=b.clone(); d[28]=0; tryDecode("zero-id-packet-type",d);
byte[] e=b.clone(); e[28]=(byte)'X'; tryDecode("X-id-packet-type",e);
// flip comment packet first byte at page1 body start (offset 58+27+16)
for (int off: new int[]{58+27+16, 58+27+16+7, 58+27+16+8, 58+27+16+11, 58+27+16+12}) { byte[] f=b.clone(); f[off]^=1; tryDecode("flip-"+off, f); }
/exit
EOF"}

