import java.nio.file.*; import java.util.*;
import resforge.audio.OggVorbis;
byte[] b=Files.readAllBytes(Path.of("src/test/resources/resforge/audio/vorbis-sample.ogg"));
void tryDecode(String name, byte[] x){ try { var p=OggVorbis.decode(x); System.out.println(name+": OK len="+p.data.length+" rate="+p.rate+" ch="+p.channels); } catch(Throwable t){ System.out.println(name+": "+t.getClass().getName()+": "+t.getMessage()); } }
int crc(byte[] data,int off,int len){ int crc=0; for(int i=0;i<len;i++){ crc ^= (data[off+i]&0xff)<<24; for(int j=0;j<8;j++){ if((crc&0x80000000)!=0) crc=(crc<<1)^0x04c11db7; else crc<<=1; } } return crc; }
int pageLen(byte[] b,int off){ int n=b[off+26]&255; int body=0; for(int i=0;i<n;i++) body+=b[off+27+i]&255; return 27+n+body; }
void fix(byte[] b,int off){ int len=pageLen(b,off); for(int i=22;i<26;i++)b[off+i]=0; int c=crc(b,off,len); for(int i=0;i<4;i++)b[off+i+22]=(byte)(c>>>(8*i)); }
tryDecode("id-magic", ()->{}); // ignore
byte[] c=b.clone(); c[28]=2; fix(c,0); tryDecode("id packet type 2 crc",c);
byte[] c2=b.clone(); c2[28+1]='X'; fix(c2,0); tryDecode("id vorbis magic X crc",c2);
byte[] c3=b.clone(); c3[28+11]=0; fix(c3,0); tryDecode("channels0 crc",c3);
byte[] c4=b.clone(); for(int i=0;i<4;i++) c4[28+12+i]=0; fix(c4,0); tryDecode("rate0 crc",c4);
byte[] c5=b.clone(); c5[28+11]=1; fix(c5,0); tryDecode("channels1 crc",c5);
byte[] c6=b.clone(); c6[28+11]=127; fix(c6,0); tryDecode("channels127 crc",c6);
byte[] c7=b.clone(); c7[101]=2; fix(c7,58); tryDecode("comment type2 crc",c7);
byte[] c8=b.clone(); c8[166]=6; fix(c8,58); tryDecode("setup type6 crc",c8);
/exit
EOF"}

