package resforge.layers;

import resforge.io.MessageReader;

import java.util.Arrays;

/**
 * Read-only decoder for the {@code mesh} (FastMesh) layer: a triangle-index list
 * referencing a {@code vbuf2} by id. It fully parses the header and the index
 * stream — including the delta-stripped form (haven.FastMesh.unstrip/decdelta) —
 * so the byte span lines up exactly with the payload ({@link #reachedEnd}), which
 * validates the decoder against real files.
 *
 * Old form (fl &amp; 0x80 == 0): uint16 num, int16 matid, optional id/ref/rdat/
 * vbufid, then num*3 indices (raw uint16, or delta-stripped if fl &amp; 32).
 * New form (fl &amp; 0x80 != 0, ver==1): int16 id, int16 vbufid, tto info map,
 * string fmt ("" raw | "strips"), uint16 num, indices.
 */
public class MeshInfo {
    public boolean recognized;
    public boolean reachedEnd;
    public int numTris;
    public int matid = -1;
    public int ref = -1;
    public int id = -1;
    public int vbufid = 0;
    public boolean modern;
    /** Verbatim modern tto metadata, including the terminating empty key. */
    public byte[] modernInfo;
    public boolean stripped;
    public short[] indices;          // num*3 vertex indices (decoded), or null

    public static MeshInfo parse(byte[] payload) {
        MeshInfo mi = new MeshInfo();
        try {
            MessageReader in = new MessageReader(payload);
            int fl = in.uint8();
            if((fl & 0x80) == 0) {
                int num = in.uint16();
                mi.matid = in.int16();
                mi.id = ((fl & 2) != 0) ? in.int16() : -1;
                mi.ref = ((fl & 4) != 0) ? in.int16() : -1;
                if((fl & 8) != 0) {
                    while(true) {
                        String k = in.string();
                        if(k.isEmpty()) break;
                        in.string();                          // value
                    }
                }
                mi.vbufid = ((fl & 16) != 0) ? in.int16() : 0;
                mi.stripped = (fl & 32) != 0;
                if((fl & ~63) != 0)
                    return mi;
                mi.numTris = num;
                mi.indices = readIndices(in, num, mi.stripped);
                mi.recognized = true;
            } else {
                int ver = fl & 0x7f;
                if(ver != 1)
                    return mi;
                mi.modern = true;
                mi.id = in.int16();
                mi.vbufid = in.int16();
                int infoStart = in.position();
                while(true) {
                    String k = in.string();
                    if(k.isEmpty()) break;
                    Integer v = TtoSkip.readIntegerValue(in);
                    if(v != null) {
                        if(k.equals("mat"))
                            mi.matid = v;
                        else if(k.equals("ref"))
                            mi.ref = v;
                    }
                }
                mi.modernInfo = Arrays.copyOfRange(payload, infoStart, in.position());
                String fmt = in.string();
                if(fmt.equals("")) {
                    mi.stripped = false;
                } else if(fmt.equals("strips")) {
                    mi.stripped = true;
                } else {
                    return mi;
                }
                mi.numTris = in.uint16();
                mi.indices = readIndices(in, mi.numTris, mi.stripped);
                mi.recognized = true;
            }
            mi.reachedEnd = in.eom();
        } catch(RuntimeException e) {
            mi.reachedEnd = false;
        }
        return mi;
    }

    private static short[] readIndices(MessageReader in, int num, boolean stripped) {
        short[] ind = new short[num * 3];
        if(stripped) {
            unstrip(in, ind);
        } else {
            for(int i = 0; i < ind.length; i++)
                ind[i] = (short) in.uint16();
        }
        return ind;
    }

    /* Faithful port of haven.FastMesh.decdelta / unstrip. */
    private static int decdelta(MessageReader in, boolean[] pickp) {
        int b = in.uint8();
        if(pickp != null)
            pickp[0] = (b & 0x80) != 0;
        int ret = b & 0x3f;
        int bits = 6;
        boolean c = (b & 0x40) != 0;
        while(c) {
            b = in.uint8();
            c = (b & 0x80) != 0;
            ret |= (b & 0x7f) << bits;
            bits += 7;
        }
        ret = signExtend(ret, bits);
        return (ret >= 0) ? ret + 1 : ret;
    }

    private static int signExtend(int v, int bits) {
        if(bits >= 32)
            return v;
        int shift = 32 - bits;
        return (v << shift) >> shift;
    }

    private static void unstrip(MessageReader in, short[] ind) {
        int f = 0, o = 0, n = ind.length / 3;
        int[] face = new int[3], nface = new int[3];
        boolean[] pick = {false};
        while(f < n) {
            ind[o++] = (short) (face[0] = in.uint16());
            ind[o++] = (short) (face[1] = face[0] + decdelta(in, null));
            ind[o++] = (short) (face[2] = face[1] + decdelta(in, null));
            f++;
            int rn = in.uint8();
            for(int ri = 0; ri < rn; ri++) {
                nface[2] = face[2] + decdelta(in, pick);
                if(!pick[0]) {
                    nface[0] = face[0];
                    nface[1] = face[2];
                } else {
                    nface[0] = face[2];
                    nface[1] = face[1];
                }
                int[] t = face; face = nface; nface = t;
                for(int i = 0; i < 3; i++)
                    ind[o++] = (short) face[i];
                f++;
            }
        }
    }
}

/*
 * ResForge — a modding tool for Haven & Hearth .res files.
 *
 * The .res binary encoding mirrors haven.Message / haven.Utils from the game
 * client. This reader reproduces the subset of decoders that the tool needs,
 * using little-endian byte order throughout (as the client does).
 */
package resforge.io;

import java.nio.ByteBuffer;
import java.nio.charset.CharacterCodingException;
import java.nio.charset.CodingErrorAction;
import java.nio.charset.StandardCharsets;

/** Sequential little-endian reader over a byte array, matching haven.Message. */
public class MessageReader {
    private final byte[] buf;
    private int pos;
    private final int end;

    public MessageReader(byte[] buf) {
        this(buf, 0, buf.length);
    }

    public MessageReader(byte[] buf, int off, int len) {
        if(off < 0 || len < 0 || off > buf.length - len)
            throw new IllegalArgumentException("invalid range off=" + off + " len=" + len + " (buf=" + buf.length + ")");
        this.buf = buf;
        this.pos = off;
        this.end = off + len;
    }

    public int position() {
        return pos;
    }

    public int remaining() {
        return end - pos;
    }

    public boolean eom() {
        return pos >= end;
    }

    private void ensure(int n) {
        if(n < 0 || n > end - pos)
            throw new IllegalStateException("Required " + n + " bytes, only " + (end - pos) + " left");
    }

    public int int8() {
        ensure(1);
        return buf[pos++];
    }

    public int uint8() {
        return int8() & 0xff;
    }

    public int int16() {
        ensure(2);
        int v = (buf[pos] & 0xff) | ((buf[pos + 1] & 0xff) << 8);
        pos += 2;
        return (short) v;
    }

    public int uint16() {
        return int16() & 0xffff;
    }

    public int int32() {
        ensure(4);
        int v = (buf[pos] & 0xff) | ((buf[pos + 1] & 0xff) << 8)
                | ((buf[pos + 2] & 0xff) << 16) | ((buf[pos + 3] & 0xff) << 24);
        pos += 4;
        return v;
    }

    public long uint32() {
        return int32() & 0xffffffffL;
    }

    public long int64() {
        ensure(8);
        long v = 0;
        for(int i = 0; i < 8; i++)
            v |= (long) (buf[pos + i] & 0xff) << (i * 8);
        pos += 8;
        return v;
    }

    public float float32() {
        return Float.intBitsToFloat(int32());
    }

    public double float64() {
        return Double.longBitsToDouble(int64());
    }

    /** IEEE-754 half-precision (16-bit) float, little-endian. */
    public float float16() {
        return halfToFloat(uint16());
    }

    /** Converts a 16-bit half-precision bit pattern to a 32-bit float (exact). */
    public static float halfToFloat(int h) {
        int sign = (h >> 15) & 0x1;
        int exp = (h >> 10) & 0x1f;
        int mant = h & 0x3ff;
        int bits;
        if(exp == 0) {
            if(mant == 0) {
                bits = sign << 31;                       // +/- 0
            } else {
                exp = 127 - 15 + 1;                      // subnormal -> normalize
                while((mant & 0x400) == 0) {
                    mant <<= 1;
                    exp--;
                }
                mant &= 0x3ff;
                bits = (sign << 31) | (exp << 23) | (mant << 13);
            }
        } else if(exp == 0x1f) {
            bits = (sign << 31) | 0x7f800000 | (mant << 13);   // inf / NaN
        } else {
            bits = (sign << 31) | ((exp - 15 + 127) << 23) | (mant << 13);
        }
        return Float.intBitsToFloat(bits);
    }

    /** Custom-packed float (haven {@code Message.cpfloat}): a signed {@code int8}
     *  exponent followed by a little-endian {@code uint32} where the top bit is the
     *  sign and the low 31 bits are the mantissa. Mirrors {@code Utils.floatd}. */
    public double cpfloat() {
        int e = int8();
        long t = uint32();
        int m = (int) (t & 0x7fffffffL);
        boolean s = (t & 0x80000000L) != 0;
        if(e == -128) {
            if(m == 0)
                return 0.0;
            throw new IllegalStateException("invalid special cpfloat (" + m + ")");
        }
        double v = (m / 2147483648.0) + 1.0;
        if(s)
            v = -v;
        return Math.pow(2.0, e) * v;
    }

    /** Signed normalized 16-bit value in [-1, 1] (haven {@code Message.snorm16}). */
    public float snorm16() {
        int v = int16();
        if(v < -0x7fff)
            v = -0x7fff;
        if(v > 0x7fff)
            v = 0x7fff;
        return v / (float) 0x7fff;
    }

    /** Unsigned normalized 16-bit value in [0, 1] (haven {@code Message.unorm16}). */
    public float unorm16() {
        return uint16() / (float) 0xffff;
    }

    /** Modular normalized 16-bit value in [0, 1) (haven {@code Message.mnorm16}). */
    public float mnorm16() {
        return uint16() / (float) 0x10000;
    }

    /** Decodes an octahedral-encoded unit vector from two snorm components into
     *  {@code out[0..2]} (mirrors {@code Utils.oct2uvec}). */
    public static void oct2uvec(float[] out, float x, float y) {
        float z = 1 - (Math.abs(x) + Math.abs(y));
        if(z < 0) {
            float xc = x, yc = y;
            x = (1 - Math.abs(yc)) * Math.copySign(1, xc);
            y = (1 - Math.abs(xc)) * Math.copySign(1, yc);
        }
        float f = 1 / (float) Math.sqrt((x * x) + (y * y) + (z * z));
        out[0] = x * f;
        out[1] = y * f;
        out[2] = z * f;
    }

    /** NUL-terminated UTF-8 string. */
    public String string() {
        int start = pos;
        while(pos < end && buf[pos] != 0)
            pos++;
        if(pos >= end)
            throw new IllegalStateException("Found no NUL terminator");
        // Strict UTF-8: reject malformed bytes rather than substituting U+FFFD, so
        // a decode -> encode is byte-identical (the lossless invariant) and a
        // non-round-trippable name/string is surfaced instead of silently changed.
        String s;
        try {
            s = StandardCharsets.UTF_8.newDecoder()
                    .onMalformedInput(CodingErrorAction.REPORT)
                    .onUnmappableCharacter(CodingErrorAction.REPORT)
                    .decode(ByteBuffer.wrap(buf, start, pos - start)).toString();
        } catch(CharacterCodingException e) {
            throw new IllegalStateException("Invalid UTF-8 string", e);
        }
        pos++;
        return s;
    }

    public byte[] bytes(int n) {
        ensure(n);
        byte[] ret = new byte[n];
        System.arraycopy(buf, pos, ret, 0, n);
        pos += n;
        return ret;
    }

    public void skip(int n) {
        ensure(n);
        pos += n;
    }
}
