            return AnimCodec.toJsonIfLossless(l.data);
        if(l.name.equals("neg"))
            return NegCodec.toJsonIfLossless(l.data);
        if(l.name.equals("obst"))
            return ObstCodec.toJsonIfLossless(l.data);
