import resforge.io.MessageReader;

/**
 * Parses an {@code audio2} layer header and locates the embedded Ogg Vorbis
 * stream so the layer can be split into a verbatim header part and a
 * replaceable {@code .ogg} part.
 *
 * Audio layer format (from haven.Resource.Audio):
 * <pre>
 *   uint8  ver                       (1..3)
 *   string id
 *   if ver == 2: uint16 vol          (bvol = vol * 0.001)
 *   if ver >= 3: repeated [string key; tto value] until key==""
 *   &lt;coded audio: an Ogg Vorbis stream, read to end of payload&gt;
 * </pre>
 *
 * The audio runs to the end of the payload (like {@code image}), so the split
 * is a plain header/tail cut — no length recomputation is needed and the parts
 * concatenate back exactly. For ver 1/2 the header is parsed precisely; for the
 * rarer ver 3 (typed metadata) the split is found by scanning for the {@code
 * OggS} signature, which is also used to validate the parsed offset.
 */
public class AudioInfo {
    public boolean recognized;
    public int ver;
    public String id = "";
    public double bvol = 1.0;
    public int audioOffset = -1;   // byte index where the Ogg stream begins
    public String format;          // "ogg" or null

    public static AudioInfo parse(byte[] payload) {
        AudioInfo ai = new AudioInfo();
        try {
            MessageReader in = new MessageReader(payload);
            int ver = in.uint8();
            if(ver >= 1 && ver <= 3) {
                ai.ver = ver;
                ai.recognized = true;
                ai.id = in.string();
                if(ver == 2)
                    ai.bvol = in.uint16() * 0.001;
                if(ver <= 2)
                    ai.audioOffset = in.position();
                /* ver 3 carries a typed metadata map; locate the audio by signature instead. */
            }
        } catch(RuntimeException e) {
            ai.recognized = false;
        }

        if(!oggAt(payload, ai.audioOffset))
            ai.audioOffset = findOgg(payload, 1);
        ai.format = oggAt(payload, ai.audioOffset) ? "ogg" : null;
        if(ai.format == null)
            ai.audioOffset = -1;
        return ai;
    }

    private static int findOgg(byte[] b, int from) {
        for(int i = Math.max(0, from); i <= b.length - 4; i++) {
            if(oggAt(b, i))
                return i;
        }
        return -1;
    }

    private static boolean oggAt(byte[] b, int i) {
        if(i < 0 || i + 4 > b.length)
            return false;
        return (b[i] & 0xff) == 0x4F && (b[i + 1] & 0xff) == 0x67
                && (b[i + 2] & 0xff) == 0x67 && (b[i + 3] & 0xff) == 0x53;
    }
}
package resforge.layers;

import resforge.io.MessageReader;

/**
 * Parses a {@code font} layer header and locates the embedded font program so
 * the layer can be split into a verbatim header part and a replaceable font
 * file (TrueType/OpenType).
 *
 * Font layer format (from haven.Resource.Font):
 * <pre>
 *   uint8 ver   (== 1)
 *   uint8 type  (== 0, TrueType)
 *   &lt;font program bytes, read to end of payload&gt;
 * </pre>
 *
 * The font runs to the end of the payload (like {@code image}/{@code audio2}),
 * so it is a plain header/tail cut. The embedded program is validated by its
 * sfnt signature.
 */
public class FontInfo {
    public boolean recognized;
    public int ver, type;
    public int fontOffset = -1;   // byte index where the font program begins
    public String format;         // "ttf", "otf", "ttc", or null

    public static FontInfo parse(byte[] payload) {
        FontInfo fi = new FontInfo();
        try {
            MessageReader in = new MessageReader(payload);
            fi.ver = in.uint8();
            if(fi.ver == 1) {
                fi.type = in.uint8();
                if(fi.type == 0) {
                    fi.recognized = true;
                    fi.fontOffset = in.position();
                }
            }
        } catch(RuntimeException e) {
            fi.recognized = false;
        }
        fi.format = fontFormatAt(payload, fi.fontOffset);
        if(fi.format == null)
            fi.fontOffset = -1;
        return fi;
    }

    private static String fontFormatAt(byte[] b, int i) {
        if(i < 0 || i + 4 > b.length)
            return null;
        int b0 = b[i] & 0xff, b1 = b[i + 1] & 0xff, b2 = b[i + 2] & 0xff, b3 = b[i + 3] & 0xff;
        if(b0 == 0x00 && b1 == 0x01 && b2 == 0x00 && b3 == 0x00)
            return "ttf";                         // sfnt 1.0 (TrueType)
        if(b0 == 'O' && b1 == 'T' && b2 == 'T' && b3 == 'O')
            return "otf";                         // OpenType with CFF
        if(b0 == 't' && b1 == 'r' && b2 == 'u' && b3 == 'e')
            return "ttf";                         // legacy TrueType
        if(b0 == 't' && b1 == 't' && b2 == 'c' && b3 == 'f')
            return "ttc";                         // TrueType collection
        return null;
    }
}

package resforge.layers;

import resforge.io.Json;
import resforge.io.MessageReader;
import resforge.io.MessageWriter;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Typed editor for the {@code action} layer (from haven.Resource.AButton): a
 * fully deterministic, fixed-shape record exposed as editable JSON.
 *
 * Action layer format:
 * <pre>
 *   string parent          (parent resource name, or "")
 *   uint16 parentVer
 *   string name
 *   string prereq          (prerequisite skill, often "")
 *   uint16 hotkey          (a key code; ASCII for letter keys)
 *   uint16 adCount
 *   string[adCount] ad     (action data / arguments)
 * </pre>
 *
 * The encoding has no type ambiguity, so decode/encode is exactly reversible;
 * {@link #toJsonIfLossless} still guards with a byte-for-byte round-trip check
 * and falls back to a raw passthrough on any surprise, so editing an action
 * layer can never corrupt a resource.
 */
public final class ActionCodec {
    private ActionCodec() {
    }

    public static class Unsupported extends RuntimeException {
        public Unsupported(String msg) {
            super(msg);
        }
    }

    public static Map<String, Object> decode(byte[] payload) {
        MessageReader in = new MessageReader(payload);
        String parent = in.string();
        int parentVer = in.uint16();
        String name = in.string();
        String prereq = in.string();
        int hotkey = in.uint16();
        int adCount = in.uint16();
        if(adCount > in.remaining())
            throw new Unsupported("implausible ad count " + adCount);
        List<Object> ad = new ArrayList<>(adCount);
        for(int i = 0; i < adCount; i++)
            ad.add(in.string());
        if(!in.eom())
            throw new Unsupported("trailing data after action record");

        Map<String, Object> model = new LinkedHashMap<>();
        model.put("parent", parent);
        model.put("parentVer", (long) parentVer);
        model.put("name", name);
        model.put("prereq", prereq);
        model.put("hotkey", (long) hotkey);
        model.put("ad", ad);
        return model;
    }

    public static byte[] encode(Map<String, Object> model) {
        MessageWriter out = new MessageWriter();
        out.string(str(model, "parent"));
        out.uint16(u16(model, "parentVer"));
        out.string(str(model, "name"));
        out.string(str(model, "prereq"));
        out.uint16(u16(model, "hotkey"));
        Object adObj = model.get("ad");
        if(!(adObj instanceof List))
            throw new Unsupported("'ad' must be a list of strings");
        List<?> ad = (List<?>) adObj;
        out.uint16(Nums.count(ad.size(), 0xffff, "ad"));
        for(Object a : ad) {
            if(!(a instanceof String))
                throw new Unsupported("'ad' entries must be strings");
            out.string((String) a);
        }
        return out.toByteArray();
    }

    public static String toJsonIfLossless(byte[] payload) {
        try {
            Map<String, Object> model = decode(payload);
            String json = Json.write(model);
            @SuppressWarnings("unchecked")
            Map<String, Object> reparsed = (Map<String, Object>) Json.parse(json);
            if(Arrays.equals(payload, encode(reparsed)))
                return json;
        } catch(RuntimeException e) {
            /* fall through to raw */
        }
        return null;
    }

    private static String str(Map<String, Object> m, String key) {
        Object v = m.get(key);
        if(!(v instanceof String))
            throw new Unsupported("'" + key + "' must be a string");
        return (String) v;
    }

    private static int u16(Map<String, Object> m, String key) {
        Object v = m.get(key);
        if(!(v instanceof Number))
            throw new Unsupported("'" + key + "' must be a number");
        long n = ((Number) v).longValue();
        if(n < 0 || n > 0xffff)
            throw new Unsupported("'" + key + "' out of uint16 range: " + n);
        return (int) n;
    }
}
