    /** Decodes a neg payload into a {@code {"center","bounds","endpoints"}} model. */
    public static Map<String, Object> decode(byte[] payload) {
        MessageReader in = new MessageReader(payload);
        List<Object> center = coord(in);
        List<Object> bounds = new ArrayList<>(3);
        for(int i = 0; i < 3; i++)
            bounds.add(coord(in));
        int en = in.uint8();
        List<Object> endpoints = new ArrayList<>(en);
        for(int i = 0; i < en; i++) {
            int id = in.uint8();
            int n = in.uint16();
            List<Object> coords = new ArrayList<>(n);
            for(int o = 0; o < n; o++)
                coords.add(coord(in));
            Map<String, Object> group = new LinkedHashMap<>();
            group.put("id", (long) id);
            group.put("coords", coords);
            endpoints.add(group);
        }
        if(!in.eom())
            throw new Unsupported("trailing data after neg endpoints");
        Map<String, Object> model = new LinkedHashMap<>();
        model.put("center", center);
        model.put("bounds", bounds);
        model.put("endpoints", endpoints);
        return model;
    }

    /** Encodes a {@code {"center","bounds","endpoints"}} model back into payload bytes. */
    public static byte[] encode(Map<String, Object> model) {
        MessageWriter out = new MessageWriter();
        writeCoord(out, model.get("center"));
        Object bounds = model.get("bounds");
        if(!(bounds instanceof List) || ((List<?>) bounds).size() != 3)
            throw new Unsupported("bounds must be a 3-element array of [x,y] coords");
        for(Object c : (List<?>) bounds)
            writeCoord(out, c);
        Object endpoints = model.get("endpoints");
        if(!(endpoints instanceof List))
            throw new Unsupported("missing/invalid endpoints list");
        List<?> groups = (List<?>) endpoints;
        out.uint8(Nums.count(groups.size(), 0xff, "neg endpoint groups"));
        for(Object gObj : groups) {
            if(!(gObj instanceof Map))
                throw new Unsupported("endpoint group is not an object");
            Map<?, ?> g = (Map<?, ?>) gObj;
            Object id = g.get("id");
            Object coords = g.get("coords");
            if(!(id instanceof Number))
                throw new Unsupported("endpoint group missing numeric id");
            if(!(coords instanceof List))
                throw new Unsupported("endpoint group missing coords list");
            out.uint8(Nums.u8(id));
            out.uint16(Nums.count(((List<?>) coords).size(), 0xffff, "neg coords"));
            for(Object c : (List<?>) coords)
                writeCoord(out, c);
        }
        return out.toByteArray();
    }

    /** Returns editable JSON for the layer, or null if it cannot round-trip losslessly. */
    public static String toJsonIfLossless(byte[] payload) {
        try {
            Map<String, Object> model = decode(payload);
            String json = Json.write(model);
            @SuppressWarnings("unchecked")
            Map<String, Object> reparsed = (Map<String, Object>) Json.parse(json);
            if(Arrays.equals(payload, encode(reparsed)))
                return json;
        } catch(RuntimeException e) {
            /* fall through to raw */
        }
        return null;
    }

    private static List<Object> coord(MessageReader in) {
        List<Object> c = new ArrayList<>(2);
        c.add((long) in.int16());
        c.add((long) in.int16());
        return c;
    }

    private static void writeCoord(MessageWriter out, Object o) {
        if(!(o instanceof List) || ((List<?>) o).size() != 2)
            throw new Unsupported("coord must be a 2-element [x,y] array");
        List<?> c = (List<?>) o;
        if(!(c.get(0) instanceof Number) || !(c.get(1) instanceof Number))
            throw new Unsupported("coord components must be numbers");
        out.int16(Nums.i16(c.get(0)));
        out.int16(Nums.i16(c.get(1)));
    }
}

package resforge.layers;

import resforge.io.Json;
import resforge.io.MessageReader;
import resforge.io.MessageWriter;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Typed editor for the {@code obst} layer (from haven.Resource.Obstacle): an
 * object's movement-collision shape — one or more polygons that block walking.
 *
 * <pre>
 *   uint8  ver                  (1 or 2)
 *   if ver == 2: string id
 *   uint8  n                    number of polygons
 *   uint8  count[0..n-1]        each polygon's point count (all counts first)
 *   then, per polygon, per point: float16 x, float16 y
 * </pre>
 *
 * The coordinates are stored as {@code float16} (tile units; the client scales by
 * the tile size). Because half-precision is lossy in general, the layer is
 * exposed as editable JSON only under the lossless-or-raw guard
 * ({@link #toJsonIfLossless}): decode → JSON → encode must reproduce the original
 * bytes exactly, otherwise it stays raw. The points are kept at their exact
 * decoded values, so an unchanged layer round-trips byte-for-byte; an edited
 * coordinate is stored at the same float16 precision the game itself uses.
 */
public final class ObstCodec {
    private ObstCodec() {
    }

    public static class Unsupported extends RuntimeException {
        public Unsupported(String msg) {
            super(msg);
        }
    }

    /** Decodes an obst payload into a {@code {"version","id"?,"polygons"}} model. */
    public static Map<String, Object> decode(byte[] payload) {
        MessageReader in = new MessageReader(payload);
        int ver = in.uint8();
        if(ver < 1 || ver > 2)
            throw new Unsupported("obst version " + ver);
        String id = (ver >= 2) ? in.string() : null;
        int n = in.uint8();
        int[] counts = new int[n];
        for(int i = 0; i < n; i++)
            counts[i] = in.uint8();
        List<Object> polygons = new ArrayList<>(n);
        for(int i = 0; i < n; i++) {
            List<Object> pts = new ArrayList<>(counts[i]);
            for(int o = 0; o < counts[i]; o++) {
                List<Object> pt = new ArrayList<>(2);
                pt.add((double) in.float16());
                pt.add((double) in.float16());
                pts.add(pt);
            }
            polygons.add(pts);
        }
        if(!in.eom())
            throw new Unsupported("trailing data after obst polygons");
        Map<String, Object> model = new LinkedHashMap<>();
        model.put("version", (long) ver);
        if(id != null)
            model.put("id", id);
        model.put("polygons", polygons);
        return model;
    }

    /** Encodes a {@code {"version","id"?,"polygons"}} model back into payload bytes. */
    public static byte[] encode(Map<String, Object> model) {
        Object verObj = model.get("version");
        if(!(verObj instanceof Number))
            throw new Unsupported("missing/invalid version");
        int ver = ((Number) verObj).intValue();
        if(ver < 1 || ver > 2)
            throw new Unsupported("obst version " + ver);
        Object polysObj = model.get("polygons");
        if(!(polysObj instanceof List))
            throw new Unsupported("missing/invalid polygons list");
        List<?> polys = (List<?>) polysObj;
        if(polys.size() > 255)
            throw new Unsupported("too many polygons (max 255)");

        MessageWriter out = new MessageWriter();
        out.uint8(ver);
        if(ver >= 2) {
            Object id = model.get("id");
            if(!(id instanceof String))
                throw new Unsupported("version 2 obst requires a string id");
            out.string((String) id);
        }
        out.uint8(polys.size());
        for(Object p : polys) {
            if(!(p instanceof List))
                throw new Unsupported("polygon is not an array of points");
            int sz = ((List<?>) p).size();
            if(sz > 255)
                throw new Unsupported("too many points in a polygon (max 255)");
            out.uint8(sz);
        }
        for(Object p : polys) {
            for(Object ptObj : (List<?>) p) {
                if(!(ptObj instanceof List) || ((List<?>) ptObj).size() != 2)
                    throw new Unsupported("point must be a 2-element [x,y] array");
                List<?> pt = (List<?>) ptObj;
                out.float16(num(pt.get(0)));
                out.float16(num(pt.get(1)));
            }
        }
        return out.toByteArray();
    }

    /** Returns editable JSON for the layer, or null if it cannot round-trip losslessly. */
    public static String toJsonIfLossless(byte[] payload) {
        try {
            Map<String, Object> model = decode(payload);
            String json = Json.write(model);
            @SuppressWarnings("unchecked")
            Map<String, Object> reparsed = (Map<String, Object>) Json.parse(json);
            if(Arrays.equals(payload, encode(reparsed)))
                return json;
        } catch(RuntimeException e) {
            /* fall through to raw */
        }
        return null;
    }

    private static float num(Object o) {
        if(!(o instanceof Number))
            throw new Unsupported("coordinate must be a number");
        return ((Number) o).floatValue();
    }
}

package resforge.layers;

import resforge.io.MessageReader;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Read-only decoder for the {@code codeentry} layer (from
 * haven.Resource.CodeEntry). It is the manifest that ties a resource's
 * {@code code} layers together: which class is the entry point for each named
 * role, what arguments it gets, and which other resources are on its classpath.
 *
 * <p>The payload is a sequence of tagged sections (parsed until end of message):
 * <ul>
 *   <li>{@code t==1}: pairs of {@code [string entryName, string className]}
 *       until an empty name.</li>
 *   <li>{@code t==2}: classpath entries {@code [string resName, uint16 ver]}
 *       until an empty name.</li>
 *   <li>{@code t==3}: like {@code t==1} but each pair is followed by a
 *       {@code tto} list of arguments.</li>
 *   <li>{@code t==4}: a single {@code tto} list of {@code ["ent", ...]} /
 *       {@code ["use", ...]} records (an alternative encoding).</li>
 * </ul>
 *
 * This tool neither runs nor edits code; it only reports the structure so a
 * modder can see what a resource does. The layer itself stays raw/lossless.
 */
public final class CodeEntryInfo {
    private static final int MAX_TTO_DEPTH = 256;

    public static final class Entry {
        public final String name;
        public final String className;
        public final String args;   // rendered tto argument list, or null

        Entry(String name, String className, String args) {
            this.name = name;
            this.className = className;
            this.args = args;
        }
    }

    public static final class Dep {
        public final String name;
        public final int ver;

        Dep(String name, int ver) {
            this.name = name;
            this.ver = ver;
        }
    }

    public boolean recognized;
    public boolean reachedEnd;
    public final List<Entry> entries = new ArrayList<>();
    public final List<Dep> classpath = new ArrayList<>();

    public static CodeEntryInfo parse(byte[] payload) {
        CodeEntryInfo ce = new CodeEntryInfo();
        try {
            MessageReader in = new MessageReader(payload);
            while(!in.eom()) {
                int t = in.uint8();
                if(t == 1 || t == 3) {
                    while(true) {
                        String en = in.string();
                        String cn = in.string();
                        if(en.isEmpty())
                            break;
                        String args = (t == 3) ? render(readList(in, 0)) : null;
                        ce.entries.add(new Entry(en, cn, args));
                    }
                } else if(t == 2) {
                    while(true) {
                        String ln = in.string();
                        if(ln.isEmpty())
                            break;
                        ce.classpath.add(new Dep(ln, in.uint16()));
                    }
                } else if(t == 4) {
                    for(Object datum : readList(in, 0)) {
                        if(!(datum instanceof List))
                            continue;
                        List<?> d = (List<?>) datum;
                        if(d.isEmpty())
                            continue;
                        String kind = String.valueOf(d.get(0));
                        if(kind.equals("ent") && d.size() >= 3) {
                            String args = d.size() > 3 ? render(d.subList(3, d.size())) : null;
                            ce.entries.add(new Entry(String.valueOf(d.get(1)), String.valueOf(d.get(2)), args));
                        } else if(kind.equals("use")) {
                            for(int o = 1; o < d.size(); o++)
                                ce.classpath.add(new Dep(String.valueOf(d.get(o)), -1));
                        }
                    }
                } else {
                    throw new IllegalStateException("unknown codeentry section tag " + t);
                }
            }
            ce.recognized = true;
            ce.reachedEnd = in.eom();
        } catch(RuntimeException e) {
            ce.recognized = false;
        }
        return ce;
    }

    /* ----- a small tto reader, just enough to render codeentry arguments ----- */

    private static List<Object> readList(MessageReader in, int depth) {
        if(depth > MAX_TTO_DEPTH)
            throw new IllegalStateException("tto nesting too deep");
        List<Object> list = new ArrayList<>();
        int t;
        while((t = in.uint8()) != 0)
            list.add(readValue(in, t, depth));
        return list;
    }

    private static Object readValue(MessageReader in, int t, int depth) {
        switch(t) {
            case 1:  return (long) in.int32();
            case 2:  return in.string();
            case 4:  return (long) in.uint8();
            case 5:  return (long) in.uint16();
            case 8:  return readList(in, depth + 1);
            case 9:  return (long) in.int8();
            case 10: return (long) in.int16();
            case 12: return null;
            case 15: return (double) in.float32();
            case 16: return in.float64();
            case 32: return readMap(in, depth + 1);
            case 33: return in.int64();
            case 34: { String nm = in.string(); int ver = in.uint16(); return "res(" + nm + "@v" + ver + ")"; }
            case 35: return "resid:" + in.uint16();
            default: throw new IllegalStateException("unhandled tto tag " + t);
        }
    }

    private static Map<String, Object> readMap(MessageReader in, int depth) {
        if(depth > MAX_TTO_DEPTH)
            throw new IllegalStateException("tto nesting too deep");
        Map<String, Object> m = new LinkedHashMap<>();
        int t;
        while((t = in.uint8()) != 0) {
            Object k = readValue(in, t, depth);
            m.put(String.valueOf(k), readValue(in, in.uint8(), depth));
        }
        return m;
    }

    private static String render(List<?> list) {
        StringBuilder sb = new StringBuilder("[");
        for(int i = 0; i < list.size(); i++) {
            if(i > 0)
                sb.append(", ");
            sb.append(renderVal(list.get(i)));
        }
        return sb.append("]").toString();
    }

    private static String renderVal(Object o) {
        if(o == null)
            return "nil";
        if(o instanceof String)
            return "\"" + o + "\"";
        if(o instanceof List)
            return render((List<?>) o);
        if(o instanceof Map) {
            StringBuilder sb = new StringBuilder("{");
            boolean first = true;
            for(Map.Entry<?, ?> e : ((Map<?, ?>) o).entrySet()) {
                if(!first)
                    sb.append(", ");
                first = false;
                sb.append(e.getKey()).append(": ").append(renderVal(e.getValue()));
            }
            return sb.append("}").toString();
        }
        return String.valueOf(o);
    }
}
