package resforge.layers;

import resforge.io.MessageReader;
import resforge.io.MessageWriter;

import java.util.ArrayList;
import java.util.List;

/**
 * Read-only decoder for the {@code manim} layer (from haven.MeshAnim.Res): a
 * mesh ("morph") animation — per-frame vertex position offsets that deform a
 * model over time (e.g. a flag rippling, a plant swaying). Unlike {@code skan}
 * (which animates bones), {@code manim} moves individual vertices directly.
 *
 * <p>Structure: {@code uint8 ver}(1), {@code int16 id}, {@code uint8 rnd} (play
 * frames in random vs sequential order), {@code float32 len}, then frames until
 * a {@code 0} terminator. Each frame is {@code uint8 fmt} (1..4), {@code float32}
 * time, {@code uint16} vertex-count, an optional quantisation header (fmt 4),
 * then run-length spans of per-vertex data whose size depends on the format:
 * <ul>
 *   <li>fmt 1: position + normal, 6×{@code float32};</li>
 *   <li>fmt 2: position only, packed {@code float9995} ({@code int32});</li>
 *   <li>fmt 3: position only, 3×{@code float16};</li>
 *   <li>fmt 4: position only, 3×{@code unorm8} dequantised by the frame header.</li>
 * </ul>
 *
 * <p>This decoder walks the structure to report frame counts and formats; it
 * neither plays nor edits the animation, and the layer stays raw/lossless.
 */
public final class MeshAnimInfo {
    public static final class Frame {
        public final float time;
        public final int fmt;
        public final int vertices;
        public final int[] idx;        // animated vertex indices (into the vbuf), or null
        public final float[] pos;      // per-animated-vertex position deltas [x,y,z]·vertices, or null

        Frame(float time, int fmt, int vertices, int[] idx, float[] pos) {
            this.time = time;
            this.fmt = fmt;
            this.vertices = vertices;
            this.idx = idx;
            this.pos = pos;
        }

        public String formatName() {
            switch(fmt) {
                case 1: return "float32 pos+nrm";
                case 2: return "float9995 pos";
                case 3: return "float16 pos";
                case 4: return "unorm8 pos";
                default: return "fmt" + fmt;
            }
        }
    }

    public boolean recognized;
    public boolean reachedEnd;
    public int ver;
    public int id;
    public boolean random;
    public float len;
    public final List<Frame> frames = new ArrayList<>();

    public static MeshAnimInfo parse(byte[] payload) {
        MeshAnimInfo mi = new MeshAnimInfo();
        try {
            MessageReader in = new MessageReader(payload);
            mi.ver = in.uint8();
            if(mi.ver != 1)
                throw new IllegalStateException("meshanim version " + mi.ver);
            mi.id = in.int16();
            mi.random = in.uint8() != 0;
            mi.len = in.float32();
            while(true) {
                int t = in.uint8();
                if(t == 0)
                    break;
                if(t > 4)
                    throw new IllegalStateException("meshanim frame format " + t);
                float tm = in.float32();
                int n = in.uint16();
                float xm = 0, xk = 0, ym = 0, yk = 0, zm = 0, zk = 0;
                if(t == 4) {
                    xm = in.float16(); xk = in.float16();
                    ym = in.float16(); yk = in.float16();
                    zm = in.float16(); zk = in.float16();
                }
                int[] idx = new int[n];
                // Position deltas captured for fmt 1/3/4 (fmt 2 = float9995 is not in
                // any sample; its bytes are still consumed, but pos is left null).
                float[] pos = (t == 2) ? null : new float[n * 3];
                int i = 0;
                while(i < n) {
                    int st = in.uint16();              // span start
                    int run = in.uint16();
                    for(int o = 0; o < run; o++) {
                        idx[i] = st + o;
                        switch(t) {
                            case 1:
                                pos[i * 3] = in.float32();
                                pos[i * 3 + 1] = in.float32();
                                pos[i * 3 + 2] = in.float32();
                                in.float32(); in.float32(); in.float32();   // normal delta (unused)
                                break;
                            case 2:
                                in.int32();
                                break;
                            case 3:
                                pos[i * 3] = in.float16();
                                pos[i * 3 + 1] = in.float16();
                                pos[i * 3 + 2] = in.float16();
                                break;
                            case 4:
                                pos[i * 3] = xm + xk * (in.uint8() / 255.0f);
                                pos[i * 3 + 1] = ym + yk * (in.uint8() / 255.0f);
                                pos[i * 3 + 2] = zm + zk * (in.uint8() / 255.0f);
                                break;
                            default:
                                throw new IllegalStateException("meshanim frame format " + t);
                        }
                        i++;
                    }
                }
                mi.frames.add(new Frame(tm, t, n, idx, pos));
            }
            mi.recognized = true;
            mi.reachedEnd = in.eom();
        } catch(RuntimeException e) {
            mi.recognized = false;
        }
        return mi;
    }

    public int totalMorphs() {
        int n = 0;
        for(Frame f : frames)
            n += f.vertices;
        return n;
    }

    /**
     * Re-encodes this animation keeping its id/order/length and every frame's time
     * and format, but replacing each frame's vertex deltas with {@code newDeltas}
     * (one dense {@code num*3} array per frame). Only fmt-3 (float16) frames are
     * supported (the only format in real data); a vertex is written when any of its
     * delta components exceeds {@code eps}, grouped into run-length spans exactly as
     * {@code haven.MeshAnim.Res} reads them.
     */
    public byte[] encodeWith(float[][] newDeltas, int num, float eps) {
        for(Frame f : frames)
            if(f.fmt != 3)
                throw new IllegalStateException("only fmt-3 manim re-encode is supported (got fmt " + f.fmt + ")");
        MessageWriter w = new MessageWriter();
        w.uint8(1).int16(id).uint8(random ? 1 : 0).float32(len);
        for(int fi = 0; fi < frames.size(); fi++) {
            float[] d = newDeltas[fi];
            List<Integer> verts = new ArrayList<>();
            for(int v = 0; v < num; v++)
                if(Math.abs(d[v * 3]) > eps || Math.abs(d[v * 3 + 1]) > eps || Math.abs(d[v * 3 + 2]) > eps)
                    verts.add(v);
            w.uint8(3).float32(frames.get(fi).time).uint16(verts.size());
            int i = 0;
            while(i < verts.size()) {
                int st = verts.get(i);
                int j = i + 1;
                while(j < verts.size() && verts.get(j) == verts.get(j - 1) + 1)
                    j++;
                w.uint16(st).uint16(j - i);
                for(int k = i; k < j; k++) {
                    int v = verts.get(k);
                    w.float16(d[v * 3]).float16(d[v * 3 + 1]).float16(d[v * 3 + 2]);
                }
                i = j;
            }
        }
        w.uint8(0);
        return w.toByteArray();
    }
}

package resforge.layers;

import resforge.io.MessageReader;
import resforge.vbuf.Vbuf2Format;

import java.util.ArrayList;
import java.util.List;

/**
 * Read-only inspector for a {@code vbuf2} (vertex buffer) layer — reports the
 * vertex count and the per-attribute formats without modifying anything. This
 * is the "read-only first" step toward 3D editing (see DESIGN-notes §8).
 *
 * Layer format (from haven.VertexBuf.VertexRes):
 * <pre>
 *   uint8 fl            ver = fl &amp; 0xf  (only 0 and 1 are valid; top nibble must be 0)
 *   if ver &gt;= 1: int16 id
 *   uint16 num          number of vertices
 *   attributes, repeated until end-of-message:
 *     string name
 *     if ver &gt;= 1: int32 sublen, then sublen bytes (length-prefixed)
 *     else (ver == 0, the form mkres emits): inline data whose size is
 *       determined by the attribute's element count and on-wire format:
 *         "name"  (bare):       num*eln float32                    (haven loadbuf)
 *         "name2" (formatted):  uint8(1) + string fmt + fmt-data   (haven loadbuf2)
 * </pre>
 *
 * The float attributes (pos/nrm/col/tex/tan/bit/otex, bare and "2"-formatted)
 * are walked exactly; the variable-length bone data (bones/bones2) and any
 * unknown attribute stop the walk (recorded in {@link #stoppedAt}). The vertex
 * count and the attributes walked so far are always reported.
 */
public class Vbuf2Info {
    public boolean recognized;
    public int ver;
    public int id;
    public int num;                              // vertex count
    public final List<String> attribs = new ArrayList<>();
    public String stoppedAt;                     // first attribute the walk could not size, or null
    public boolean fullyWalked;                  // reached end-of-message cleanly

    public static Vbuf2Info parse(byte[] payload) {
        Vbuf2Info vi = new Vbuf2Info();
        try {
            MessageReader in = new MessageReader(payload);
            int fl = in.uint8();
            vi.ver = fl & 0xf;
            if((fl & ~0xf) != 0 || vi.ver >= 2)
                return vi;
            if(vi.ver >= 1)
                vi.id = in.int16();
            vi.num = in.uint16();
            vi.recognized = true;

            while(!in.eom()) {
                String name = in.string();
                if(vi.ver >= 1) {
                    int sublen = in.int32();
                    int at = in.position();
                    vi.attribs.add(name + "(" + peekFmt(payload, at) + ")");
                    in.skip(sublen);
                    continue;
                }
                if(name.equals("bones") || name.equals("bones2")) {
                    String wfmt = walkBones(in, name.equals("bones2"));
                    vi.attribs.add(name + "(" + wfmt + ")");
                    continue;
                }
                int eln = Vbuf2Format.elements(name);
                if(eln < 0) {
                    vi.stoppedAt = name;
                    return vi;
                }
                long cap = (long) vi.num * eln;
                if(name.endsWith("2")) {
                    in.uint8();                 // data version (== 1)
                    String fmt = in.string();
                    long sz = dataSize(fmt, cap);
                    if(sz < 0) {
                        vi.stoppedAt = name + ":" + fmt;
                        return vi;
                    }
                    in.skip((int) sz);
                    vi.attribs.add(name + "(" + fmt + ")");
                } else {
                    in.skip((int) (cap * 4));
                    vi.attribs.add(name + "(bare)");
                }
            }
            vi.fullyWalked = true;
        } catch(RuntimeException e) {
            vi.stoppedAt = (vi.stoppedAt != null) ? vi.stoppedAt : "<error>";
        }
        return vi;
    }

    /** Consumes inline bone data (haven.PoseMorph): per-bone run-length-coded
     *  per-vertex weight spans. Returns the weight format. */
    private static String walkBones(MessageReader in, boolean v2) {
        String wfmt = "f4";
        if(v2) {
            in.uint8();              // bone-data version (== 1)
            wfmt = in.string();      // weight format
        }
        in.uint8();                  // mba (max bones per vertex)
        int wsz;
        switch(wfmt) {
            case "f4": wsz = 4; break;
            case "un2": wsz = 2; break;
            case "un1": wsz = 1; break;
            default: throw new IllegalStateException("unknown bone-weight format: " + wfmt);
        }
        while(true) {
            String bone = in.string();
            if(bone.isEmpty())
                break;
            while(true) {
                int run = in.uint16();
                in.uint16();          // starting vertex index
                if(run == 0)
                    break;
                in.skip(run * wsz);
            }
        }
        return wfmt;
    }

    private static String peekFmt(byte[] b, int at) {
        try {
            MessageReader in = new MessageReader(b, at, b.length - at);
            in.uint8();
            return in.string();
        } catch(RuntimeException e) {
            return "?";
        }
    }

    /** Byte size of a formatted float attribute's data for {@code cap} total elements. */
    private static long dataSize(String fmt, long cap) {
        switch(fmt) {
            case "f4":     return cap * 4;
            case "f2":     return cap * 2;
            case "f1":     return cap;
            case "sf9995": return (cap / 3) * 4;
            case "sn4": case "un4": return 4 + cap * 4;
            case "sn2": case "un2": return 4 + cap * 2;
            case "sn1": case "un1": return 4 + cap;
            case "rn4":    return 8 + cap * 4;
            case "rn2":    return 8 + cap * 2;
            case "rn1":    return 8 + cap;
            case "uvech":  return cap / 3;
            case "uvec1":  return (cap / 3) * 2;
            case "uvec2":  return (cap / 3) * 4;
            default:       return -1;
        }
    }
}
