package resforge.layers;

import resforge.io.MessageReader;

import java.nio.charset.StandardCharsets;

/**
 * Read-only decoder for the {@code src} layer (from haven.Resource): an embedded
 * source file. The payload is a {@code uint8} version, a NUL-terminated file
 * name (e.g. {@code Tree.java}), and then the file's bytes (the rest of the
 * payload). Resources that ship server-authored code (see {@link CodeInfo})
 * also carry the corresponding pre-processed Java source in {@code src} layers.
 *
 * <p>This tool neither compiles nor edits the source; it only surfaces the file
 * name and contents so a modder can read what a resource is built from. The
 * layer itself stays raw/lossless.
 */
public final class SrcInfo {
    public boolean recognized;
    public int ver;
    public String fileName;
    public byte[] source;          // the embedded file bytes

    public static SrcInfo parse(byte[] payload) {
        SrcInfo si = new SrcInfo();
        try {
            MessageReader in = new MessageReader(payload);
            si.ver = in.uint8();
            si.fileName = in.string();
            si.source = in.bytes(in.remaining());
            si.recognized = true;
        } catch(RuntimeException e) {
            si.recognized = false;
        }
        return si;
    }

    /** The embedded source decoded as UTF-8 text. */
    public String text() {
        return source == null ? "" : new String(source, StandardCharsets.UTF_8);
    }
}

public static BufferedImage preview(Layer l) {
    try {
        return previewChecked(l);
    } catch(RuntimeException e) {
        /* no preview */
    }
    return null;
}

/** Bounded preview decode that preserves the reason a preview was rejected. */
static BufferedImage previewChecked(Layer l) throws PreviewFailure {
    ImagePreviewLoader.Range source = ImagePreviewLoader.embedded(l).locate();
    if(source == null)
        return null;
    String kind = l.name + " preview";
    PreviewBudget.encodedImageBytes(source.length(), kind);
    byte[] image = Arrays.copyOfRange(source.payload(), source.offset(),
            source.offset() + source.length());
    return PreviewBudget.decode(image, kind);
}

/** The embedded encoded-image bytes for image/tex layers, else null. */
public static byte[] embeddedImage(Layer l) {
    if(l.name.equals("image")) {
        ImageInfo ii = ImageInfo.parse(l.data);
        if(ii.imageFormat != null && ii.imageOffset > 0)
            return Arrays.copyOfRange(l.data, ii.imageOffset, l.data.length);
    } else if(l.name.equals("tex")) {
        TexInfo ti = TexInfo.parse(l.data);
        if(ti.found)
            return Arrays.copyOfRange(l.data, ti.imageOffset, ti.imageOffset + ti.imageLen);
    } else if(l.name.equals("tile")) {
        TileInfo ti = TileInfo.parse(l.data);
        if(ti.found)
            return Arrays.copyOfRange(l.data, ti.imageOffset, l.data.length);
    }
    return null;
}

/** The embedded Ogg Vorbis bytes for an audio2 layer, else null. */
public static byte[] audioBytes(Layer l) {
    if(l.name.equals("audio2")) {
        AudioInfo ai = AudioInfo.parse(l.data);
        if(ai.format != null && ai.audioOffset > 0)
            return Arrays.copyOfRange(l.data, ai.audioOffset, l.data.length);
    }
    return null;
}

/** Editable plain text for tooltip/pagina, else null. */
public static String editableText(Layer l) {
    if(!l.name.equals("tooltip") && !l.name.equals("pagina"))
        return null;
    try {
        String text = StandardCharsets.UTF_8.newDecoder()
                .onMalformedInput(CodingErrorAction.REPORT)
                .onUnmappableCharacter(CodingErrorAction.REPORT)
                .decode(ByteBuffer.wrap(l.data))
                .toString();
        return Arrays.equals(l.data, text.getBytes(StandardCharsets.UTF_8)) ? text : null;
    } catch(CharacterCodingException e) {
        return null;
