package resforge.layers;

import resforge.io.MessageReader;

/**
 * Parses an {@code audio2} layer header and locates the embedded Ogg Vorbis
 * stream so the layer can be split into a verbatim header part and a
 * replaceable {@code .ogg} part.
 *
 * Audio layer format (from haven.Resource.Audio):
 * <pre>
 *   uint8  ver                       (1..3)
 *   string id
 *   if ver == 2: uint16 vol          (bvol = vol * 0.001)
 *   if ver >= 3: repeated [string key; tto value] until key==""
 *   &lt;coded audio: an Ogg Vorbis stream, read to end of payload&gt;
 * </pre>
 *
 * The audio runs to the end of the payload (like {@code image}), so the split
 * is a plain header/tail cut — no length recomputation is needed and the parts
 * concatenate back exactly. For ver 1/2 the header is parsed precisely; for the
 * rarer ver 3 (typed metadata) the split is found by scanning for the {@code
 * OggS} signature, which is also used to validate the parsed offset.
 */
public class AudioInfo {
    public boolean recognized;
    public int ver;
    public String id = "";
    public double bvol = 1.0;
    public int audioOffset = -1;   // byte index where the Ogg stream begins
    public String format;          // "ogg" or null

    public static AudioInfo parse(byte[] payload) {
        AudioInfo ai = new AudioInfo();
        try {
            MessageReader in = new MessageReader(payload);
            int ver = in.uint8();
            if(ver >= 1 && ver <= 3) {
                ai.ver = ver;
                ai.recognized = true;
                ai.id = in.string();
                if(ver == 2)
                    ai.bvol = in.uint16() * 0.001;
                if(ver <= 2)
                    ai.audioOffset = in.position();
                /* ver 3 carries a typed metadata map; locate the audio by signature instead. */
            }
        } catch(RuntimeException e) {
            ai.recognized = false;
        }

        if(!oggAt(payload, ai.audioOffset))
            ai.audioOffset = findOgg(payload, 1);
        ai.format = oggAt(payload, ai.audioOffset) ? "ogg" : null;
        if(ai.format == null)
            ai.audioOffset = -1;
        return ai;
    }

    private static int findOgg(byte[] b, int from) {
        for(int i = Math.max(0, from); i <= b.length - 4; i++) {
            if(oggAt(b, i))
                return i;
        }
        return -1;
    }

    private static boolean oggAt(byte[] b, int i) {
        if(i < 0 || i + 4 > b.length)
            return false;
        return (b[i] & 0xff) == 0x4F && (b[i + 1] & 0xff) == 0x67
                && (b[i + 2] & 0xff) == 0x67 && (b[i + 3] & 0xff) == 0x53;
    }
}

package resforge.layers;

import resforge.io.MessageReader;

/**
 * Parses a {@code tex} (texture) layer header and locates the embedded color
 * image so the layer can be split into a verbatim header part, a replaceable
 * image part, and a verbatim trailing part.
 *
 * Tex layer format (from haven.TexR.Encoded):
 * <pre>
 *   int16  id
 *   uint16 off.x, off.y
 *   uint16 sz.x,  sz.y
 *   parts, repeated until end-of-message:
 *     uint8 tag                      fl = (tag &amp; 0xc0) >> 6 ; t = tag &amp; 0x3f
 *       fl == 0: inline part read straight from the stream
 *         t == 0: color image  -> int32 len, then len encoded-image bytes
 *         t == 4: alpha mask    -> int32 len, then len encoded-image bytes
 *         t == 1|2|3: filter    -> 1 byte
 *         t == 5: linear flag   -> 0 bytes
 *       fl == 1: length-prefixed sub-message, uint8 length
 *       fl == 2: length-prefixed sub-message, uint8 + int32 length
 * </pre>
 *
 * Only the first color image (t==0, fl==0 — the form used by real resources) is
 * exposed; everything else (filters, mask, length-prefixed parts) is preserved
 * verbatim. If the color image cannot be located cleanly, {@link #found} is
 * false and the caller should fall back to a raw passthrough.
 */
public class TexInfo {
    public boolean recognized;     // header parsed
    public boolean found;          // inline color image located
    public int id;
    public int offX, offY, szX, szY;
    public int lenFieldPos = -1;   // index of the color image's int32 length field
    public int imageOffset = -1;   // index where the color image bytes begin
    public int imageLen = -1;      // color image byte length
    public String imageFormat;     // "png", "jpg", ... or null

    public boolean maskFound;          // inline alpha-mask image located (tag 4)
    public int maskLenFieldPos = -1;   // index of the mask's int32 length field
    public int maskOffset = -1;        // index where the mask image bytes begin
    public int maskLen = -1;           // mask image byte length
    public String maskFormat;          // "png", ... or null

    public static TexInfo parse(byte[] data) {
        TexInfo t = new TexInfo();
        try {
            MessageReader in = new MessageReader(data);
            t.id = in.int16();
            t.offX = in.uint16();
            t.offY = in.uint16();
            t.szX = in.uint16();
            t.szY = in.uint16();
            t.recognized = true;

            // Scan the whole part stream so both the color image (tag 0) and the
            // optional alpha mask (tag 4) are located. Once the color image is found
            // any later parsing trouble simply stops the scan with the color result
            // intact (the mask is optional), so this never weakens the color split.
            while(!in.eom()) {
                int tag = in.uint8();
                int fl = (tag & 0xc0) >> 6;
                int pt = tag & 0x3f;
                if(fl == 0) {
                    if(pt == 0 || pt == 4) {
                        int lenPos = in.position();
                        int len = in.int32();
                        int imgStart = in.position();
                        if(len < 0 || (long) imgStart + len > data.length)
                            return t.found ? t : fail(t);
                        String fmt = ImageMagic.formatAt(data, imgStart);
                        if(pt == 0 && t.imageOffset < 0) {
                            t.lenFieldPos = lenPos;
                            t.imageOffset = imgStart;
                            t.imageLen = len;
                            t.imageFormat = fmt;
                            t.found = (fmt != null);
                            if(!t.found)
                                return t;        // color isn't a real image -> raw passthrough
                        } else if(pt == 4 && !t.maskFound) {
                            t.maskLenFieldPos = lenPos;
                            t.maskOffset = imgStart;
                            t.maskLen = len;
                            t.maskFormat = fmt;
                            t.maskFound = (fmt != null);
                        }
                        in.skip(len);
                    } else if(pt == 1 || pt == 2 || pt == 3) {
                        in.skip(1);
                    } else if(pt == 5) {
                        /* no payload */
                    } else {
                        return t.found ? t : fail(t);
                    }
                } else if(fl == 1) {
                    in.skip(in.uint8());
                } else if(fl == 2) {
                    in.skip(1);
                    int n = in.int32();
                    if(n < 0 || (long) in.position() + n > data.length)
                        return t.found ? t : fail(t);
                    in.skip(n);
                } else {
                    return t.found ? t : fail(t);
                }
            }
        } catch(RuntimeException e) {
            return t.found ? t : fail(t);
        }
        return t;
    }

    private static TexInfo fail(TexInfo t) {
        t.found = false;
        t.lenFieldPos = -1;
        t.imageOffset = -1;
        t.imageLen = -1;
        return t;
    }
}

