package resforge.layers;

import resforge.io.Json;
import resforge.io.MessageReader;
import resforge.io.MessageWriter;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Typed editor for the {@code anim} layer (from haven.Resource.Anim): a simple,
 * fully deterministic sprite-animation record —
 *
 * <pre>
 *   int16  id        (animation id; often -1)
 *   uint16 delay     (frame duration in ms — the animation speed)
 *   uint16 n         (frame count)
 *   int16[n] frames  (the image-layer id shown in each frame)
 * </pre>
 *
 * The frames reference {@code image} layers in the same resource by their id, so
 * editing an {@code anim} changes the animation speed or the frame sequence while
 * the pixels stay in the (separately editable) image layers.
 *
 * Because the format has no type ambiguity it is exposed as editable JSON
 * {@code {"id":…,"delay":…,"frames":[…]}} with the usual lossless-or-raw guard:
 * {@link #toJsonIfLossless} only offers JSON when decode → encode reproduces the
 * original bytes exactly.
 */
public final class AnimCodec {
    private AnimCodec() {
    }

    public static class Unsupported extends RuntimeException {
        public Unsupported(String msg) {
            super(msg);
        }
    }

    /** Decodes an anim payload into a {@code {"id":N,"delay":N,"frames":[…]}} model. */
    public static Map<String, Object> decode(byte[] payload) {
        MessageReader in = new MessageReader(payload);
        int id = in.int16();
        int delay = in.uint16();
        int n = in.uint16();
        List<Object> frames = new ArrayList<>(n);
        for(int i = 0; i < n; i++)
            frames.add((long) in.int16());
        if(!in.eom())
            throw new Unsupported("trailing data after anim frames");
        Map<String, Object> model = new LinkedHashMap<>();
        model.put("id", (long) id);
        model.put("delay", (long) delay);
        model.put("frames", frames);
        return model;
    }

    /** Encodes a {@code {"id":N,"delay":N,"frames":[…]}} model back into payload bytes. */
    public static byte[] encode(Map<String, Object> model) {
        Object id = model.get("id");
        Object delay = model.get("delay");
        Object frames = model.get("frames");
        if(!(id instanceof Number))
            throw new Unsupported("missing/invalid id");
        if(!(delay instanceof Number))
            throw new Unsupported("missing/invalid delay");
        if(!(frames instanceof List))
            throw new Unsupported("missing/invalid frames list");
        List<?> f = (List<?>) frames;
        MessageWriter out = new MessageWriter();
        out.int16(Nums.i16(id));
        out.uint16(Nums.u16(delay));
        out.uint16(Nums.count(f.size(), 0xffff, "anim frames"));
        for(Object fr : f) {
            if(!(fr instanceof Number))
                throw new Unsupported("frame id is not a number");
            out.int16(Nums.i16(fr));
        }
        return out.toByteArray();
    }

    /** Returns editable JSON for the layer, or null if it cannot round-trip losslessly. */
    public static String toJsonIfLossless(byte[] payload) {
        try {
            Map<String, Object> model = decode(payload);
            String json = Json.write(model);
            @SuppressWarnings("unchecked")
            Map<String, Object> reparsed = (Map<String, Object>) Json.parse(json);
            if(Arrays.equals(payload, encode(reparsed)))
                return json;
        } catch(RuntimeException e) {
            /* fall through to raw */
        }
        return null;
    }
}

package resforge.layers;

import resforge.io.Json;
import resforge.io.MessageReader;
import resforge.io.MessageWriter;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Typed editor for the {@code neg} layer (from haven.Resource.Neg): an object's
 * 2D interaction geometry — where you click it and any connection points.
 *
 * <pre>
 *   coord  center                 int16 x, int16 y  (the click hotspot)
 *   12 bytes = 3 coords           the client skips these; CarryGun reads them as
 *                                 tl/br/oc (top-left/bottom-right/object-center)
 *   uint8  en                     number of endpoint groups
 *   per group: uint8 id, uint16 n, n × coord
 * </pre>
 *
 * Every field is an {@code int16}/{@code uint8}/{@code uint16}, so the layer is
 * exactly reversible and is exposed as editable JSON
 * {@code {"center":[x,y],"bounds":[[x,y],[x,y],[x,y]],"endpoints":[{"id":N,"coords":[[x,y],…]}]}}
 * under the lossless-or-raw guard ({@link #toJsonIfLossless}). The endpoint
 * groups are kept as an ordered list (preserving order and any repeated ids) so
 * the bytes round-trip exactly.
 */
public final class NegCodec {
    private NegCodec() {
    }

    public static class Unsupported extends RuntimeException {
        public Unsupported(String msg) {
            super(msg);
        }
    }

    /** Decodes a neg payload into a {@code {"center","bounds","endpoints"}} model. */
    public static Map<String, Object> decode(byte[] payload) {
        MessageReader in = new MessageReader(payload);
        List<Object> center = coord(in);
        List<Object> bounds = new ArrayList<>(3);
        for(int i = 0; i < 3; i++)
            bounds.add(coord(in));
        int en = in.uint8();
        List<Object> endpoints = new ArrayList<>(en);
        for(int i = 0; i < en; i++) {
            int id = in.uint8();
            int n = in.uint16();
            List<Object> coords = new ArrayList<>(n);
            for(int o = 0; o < n; o++)
                coords.add(coord(in));
            Map<String, Object> group = new LinkedHashMap<>();
            group.put("id", (long) id);
            group.put("coords", coords);
            endpoints.add(group);
        }
        if(!in.eom())
            throw new Unsupported("trailing data after neg endpoints");
        Map<String, Object> model = new LinkedHashMap<>();
        model.put("center", center);
        model.put("bounds", bounds);
        model.put("endpoints", endpoints);
        return model;
    }

    /** Encodes a {@code {"center","bounds","endpoints"}} model back into payload bytes. */
    public static byte[] encode(Map<String, Object> model) {
        MessageWriter out = new MessageWriter();
        writeCoord(out, model.get("center"));
        Object bounds = model.get("bounds");
        if(!(bounds instanceof List) || ((List<?>) bounds).size() != 3)
            throw new Unsupported("bounds must be a 3-element array of [x,y] coords");
        for(Object c : (List<?>) bounds)
            writeCoord(out, c);
        Object endpoints = model.get("endpoints");
        if(!(endpoints instanceof List))
            throw new Unsupported("missing/invalid endpoints list");
        List<?> groups = (List<?>) endpoints;
        out.uint8(Nums.count(groups.size(), 0xff, "neg endpoint groups"));
        for(Object gObj : groups) {
            if(!(gObj instanceof Map))
                throw new Unsupported("endpoint group is not an object");
            Map<?, ?> g = (Map<?, ?>) gObj;
            Object id = g.get("id");
            Object coords = g.get("coords");
            if(!(id instanceof Number))
                throw new Unsupported("endpoint group missing numeric id");
            if(!(coords instanceof List))
                throw new Unsupported("endpoint group missing coords list");
            out.uint8(Nums.u8(id));
            out.uint16(Nums.count(((List<?>) coords).size(), 0xffff, "neg coords"));
            for(Object c : (List<?>) coords)
                writeCoord(out, c);
        }
        return out.toByteArray();
    }

    /** Returns editable JSON for the layer, or null if it cannot round-trip losslessly. */
    public static String toJsonIfLossless(byte[] payload) {
        try {
            Map<String, Object> model = decode(payload);
            String json = Json.write(model);
            @SuppressWarnings("unchecked")
            Map<String, Object> reparsed = (Map<String, Object>) Json.parse(json);
            if(Arrays.equals(payload, encode(reparsed)))
                return json;
        } catch(RuntimeException e) {
            /* fall through to raw */
        }
        return null;
    }

    private static List<Object> coord(MessageReader in) {
        List<Object> c = new ArrayList<>(2);
        c.add((long) in.int16());
        c.add((long) in.int16());
        return c;
    }

    private static void writeCoord(MessageWriter out, Object o) {
        if(!(o instanceof List) || ((List<?>) o).size() != 2)
            throw new Unsupported("coord must be a 2-element [x,y] array");
        List<?> c = (List<?>) o;
        if(!(c.get(0) instanceof Number) || !(c.get(1) instanceof Number))
            throw new Unsupported("coord components must be numbers");
        out.int16(Nums.i16(c.get(0)));
        out.int16(Nums.i16(c.get(1)));
    }
}

package resforge.layers;

import resforge.io.Json;
import resforge.io.MessageReader;
import resforge.io.MessageWriter;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Typed editor for the {@code action} layer (from haven.Resource.AButton): a
 * fully deterministic, fixed-shape record exposed as editable JSON.
 *
 * Action layer format:
 * <pre>
 *   string parent          (parent resource name, or "")
 *   uint16 parentVer
 *   string name
 *   string prereq          (prerequisite skill, often "")
 *   uint16 hotkey          (a key code; ASCII for letter keys)
 *   uint16 adCount
 *   string[adCount] ad     (action data / arguments)
 * </pre>
 *
 * The encoding has no type ambiguity, so decode/encode is exactly reversible;
 * {@link #toJsonIfLossless} still guards with a byte-for-byte round-trip check
 * and falls back to a raw passthrough on any surprise, so editing an action
 * layer can never corrupt a resource.
 */
public final class ActionCodec {
    private ActionCodec() {
    }

    public static class Unsupported extends RuntimeException {
        public Unsupported(String msg) {
            super(msg);
        }
    }

    public static Map<String, Object> decode(byte[] payload) {
        MessageReader in = new MessageReader(payload);
        String parent = in.string();
        int parentVer = in.uint16();
        String name = in.string();
        String prereq = in.string();
        int hotkey = in.uint16();
        int adCount = in.uint16();
        if(adCount > in.remaining())
            throw new Unsupported("implausible ad count " + adCount);
        List<Object> ad = new ArrayList<>(adCount);
        for(int i = 0; i < adCount; i++)
            ad.add(in.string());
        if(!in.eom())
            throw new Unsupported("trailing data after action record");

        Map<String, Object> model = new LinkedHashMap<>();
        model.put("parent", parent);
        model.put("parentVer", (long) parentVer);
        model.put("name", name);
        model.put("prereq", prereq);
        model.put("hotkey", (long) hotkey);
        model.put("ad", ad);
        return model;
    }

    public static byte[] encode(Map<String, Object> model) {
        MessageWriter out = new MessageWriter();
        out.string(str(model, "parent"));
        out.uint16(u16(model, "parentVer"));
        out.string(str(model, "name"));
        out.string(str(model, "prereq"));
        out.uint16(u16(model, "hotkey"));
        Object adObj = model.get("ad");
        if(!(adObj instanceof List))
            throw new Unsupported("'ad' must be a list of strings");
        List<?> ad = (List<?>) adObj;
        out.uint16(Nums.count(ad.size(), 0xffff, "ad"));
        for(Object a : ad) {
            if(!(a instanceof String))
                throw new Unsupported("'ad' entries must be strings");
            out.string((String) a);
        }
        return out.toByteArray();
    }

    public static String toJsonIfLossless(byte[] payload) {
        try {
            Map<String, Object> model = decode(payload);
            String json = Json.write(model);
            @SuppressWarnings("unchecked")
            Map<String, Object> reparsed = (Map<String, Object>) Json.parse(json);
            if(Arrays.equals(payload, encode(reparsed)))
                return json;
        } catch(RuntimeException e) {
            /* fall through to raw */
        }
        return null;
    }

    private static String str(Map<String, Object> m, String key) {
        Object v = m.get(key);
        if(!(v instanceof String))
            throw new Unsupported("'" + key + "' must be a string");
        return (String) v;
    }

    private static int u16(Map<String, Object> m, String key) {
        Object v = m.get(key);
        if(!(v instanceof Number))
            throw new Unsupported("'" + key + "' must be a number");
        long n = ((Number) v).longValue();
        if(n < 0 || n > 0xffff)
            throw new Unsupported("'" + key + "' out of uint16 range: " + n);
        return (int) n;
    }
}

package resforge.layers;

import resforge.io.Json;
import resforge.io.MessageReader;
import resforge.io.MessageWriter;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Base64;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Typed editor for the {@code props} layer (from haven.Resource.Props): a
 * version byte followed by a {@code tto} list of alternating string keys and
 * values. It is exposed as editable JSON, but only when the round-trip is
 * provably lossless — {@link #toJsonIfLossless} decodes, re-serializes to JSON,
 * re-encodes, and returns the JSON only if it reproduces the original bytes
 * exactly. Otherwise the caller falls back to a raw passthrough, so a props
 * layer can never be corrupted.
 *
 * <p>Each value is rendered with an explicit type tag so the exact {@code tto}
 * encoding is preserved — the same tagged-value form {@link Mat2Codec} uses. A
 * string stays a plain JSON string; every other value is a single-entry object
 * naming its exact {@code tto} type, e.g. {@code {"u8":50}}, {@code {"f32":0.5}},
 * {@code {"color":[204,204,204,255]}}, {@code {"coord":[x,y]}},
 * {@code {"bytes":"<base64>"}}, {@code {"list":[…]}} or {@code {"map":{…}}}.
 * Tagging everything (rather than leaving integers/lists/maps bare) makes a JSON
 * object unambiguously a tag, records the exact wire width instead of re-deriving
 * it, and keeps this codec symmetric with {@link Mat2Codec}.
 *
 * <p>Supported value types: string, nil, the integer widths (u8/u16/i8/i16/int/
 * long), float32/float64, color, fcolor, coord, fcoord32/fcoord64, byte blobs
 * (base64), uid, resid, resource specs, and nested list/map. The remaining
 * {@code tto} types (float8/float16 and the snorm/unorm/mnorm numbers) are not
 * modelled and simply keep the layer raw, since their round-trip is not provably
 * byte-exact.
 */
public final class PropsCodec {
    private static final int T_END = 0;
    private static final int T_INT = 1;
    private static final int T_STR = 2;
    private static final int T_COORD = 3;
    private static final int T_UINT8 = 4;
    private static final int T_UINT16 = 5;
    private static final int T_COLOR = 6;
    private static final int T_FCOLOR = 7;
    private static final int T_TTOL = 8;
    private static final int T_INT8 = 9;
    private static final int T_INT16 = 10;
    private static final int T_NIL = 12;
    private static final int T_UID = 13;
    private static final int T_BYTES = 14;
    private static final int T_FLOAT32 = 15;
    private static final int T_FLOAT64 = 16;
    private static final int T_FCOORD32 = 18;
    private static final int T_FCOORD64 = 19;
    private static final int T_MAP = 32;
    private static final int T_LONG = 33;
    private static final int T_RESSPEC = 34;
    private static final int T_RESID = 35;

    /** Hard cap on tto list/map nesting, so a crafted payload fails with a clear
     *  {@link Unsupported} (a {@code RuntimeException}, caught by the lossless-or-raw
     *  guard) instead of a {@link StackOverflowError}. Real props nest a level or two. */
    private static final int MAX_DEPTH = 256;

    private PropsCodec() {
    }

    public static class Unsupported extends RuntimeException {
        public Unsupported(String msg) {
            super(msg);
        }
    }

    /** Decodes a props payload into a {@code {"version":1,"props":{...}}} model. */
    public static Map<String, Object> decode(byte[] payload) {
        MessageReader in = new MessageReader(payload);
        int ver = in.uint8();
        if(ver != 1)
            throw new Unsupported("props version " + ver);
        List<Object> flat = new ArrayList<>();
        while(!in.eom()) {
            int t = in.uint8();
            if(t == T_END)
                break;
            flat.add(readValue(in, t, 0));
        }
        if(!in.eom())
            throw new Unsupported("trailing data after props list");
        if((flat.size() & 1) != 0)
            throw new Unsupported("props list is not key/value pairs");
        Map<String, Object> props = new LinkedHashMap<>();
        for(int a = 0; a < flat.size(); a += 2) {
            Object key = flat.get(a);
            if(!(key instanceof String))
                throw new Unsupported("non-string props key");
            if(props.containsKey(key))
                throw new Unsupported("duplicate props key: " + key);
