                case "rotate_q": {
                    out.uint8(17);
                    out.uint16(turns(op.get("angleTurns")));
                    int[] oct = octPair(op.get("axisOct"), "axisOct");
                    out.int16(oct[0]).int16(oct[1]);
                    break;
