                case "eqpoint":
                    out.uint8(2);
                    out.string(str(op.get("bone"), "bone"));
                    break;
                case "bonealign": {
                    out.uint8(3);
                    double[] ref = vec3(op.get("ref"), "ref");
                    out.cpfloat(ref[0]).cpfloat(ref[1]).cpfloat(ref[2]);
                    out.string(str(op.get("from"), "from")).string(str(op.get("to"), "to"));
                    break;
                }
                case "bonealign_q": {
                    out.uint8(19);
