import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.Arguments;
import org.junit.jupiter.params.provider.MethodSource;
import resforge.io.Json;
import resforge.io.MessageWriter;
import resforge.res.Layer;

import java.io.ByteArrayOutputStream;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.Map;
import java.util.stream.Stream;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNotSame;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.junit.jupiter.params.provider.Arguments.arguments;

class GuiSupportExportTests {
    private static final byte[] PNG = {
            (byte) 0x89, (byte) 0x50, (byte) 0x4E, (byte) 0x47,
            (byte) 0x0D, (byte) 0x0A, (byte) 0x1A, (byte) 0x0A
    };
    private static final byte[] JPEG = {(byte) 0xFF, (byte) 0xD8, (byte) 0xFF};
    private static final byte[] GIF = {'G', 'I', 'F', '8'};
    private static final byte[] BMP = {'B', 'M'};
    private static final byte[] OGG = ascii("OggS\u0000\u0002payload");
    private static final byte[] CLASS_FILE = {
            (byte) 0xCA, (byte) 0xFE, (byte) 0xBA, (byte) 0xBE,
            0x00, 0x00, 0x00, 0x34, 0x01, 0x02, 0x03
    };

    @ParameterizedTest(name = "image/{0}")
    @MethodSource("imageFormats")
    void imageExportExtractsTheEmbeddedImageAndNamesItsFormat(String format, String expectedDescription,
                                                               byte[] image) {
        byte[] payload = imagePayload(image);

        GuiSupport.Export exported = GuiSupport.export(new Layer("image", payload));

        assertEquals(format, exported.ext);
        assertEquals(expectedDescription, exported.desc);
        assertArrayEquals(image, exported.data);
        assertNotSame(payload, exported.data);
    }

    static Stream<Arguments> imageFormats() {
        return Stream.of(
                arguments("png", "PNG image", concat(PNG, ascii("image-bytes"))),
                arguments("jpg", "JPG image", concat(JPEG, ascii("image-bytes"))),
                arguments("gif", "GIF image", concat(GIF, ascii("image-bytes"))),
                arguments("bmp", "BMP image", concat(BMP, ascii("image-bytes")))
        );
    }

    @Test
    void imageExportSupportsTheTypedHeaderForm() {
        byte[] image = concat(PNG, ascii("typed-image"));
        byte[] payload = new MessageWriter()
                .uint8(129)
                .int16(42)
                .string("")
                .bytes(image)
                .toByteArray();

        GuiSupport.Export exported = GuiSupport.export(new Layer("image", payload));

        assertEquals("png", exported.ext);
        assertEquals("PNG image", exported.desc);
        assertArrayEquals(image, exported.data);
    }

    @Test
    void texExportExtractsOnlyTheDeclaredColorImage() {
        byte[] image = concat(PNG, ascii("texture-pixels"));
        byte[] payload = new MessageWriter()
                .int16(7)
                .uint16(12)
                .uint16(34)
                .uint16(64)
                .uint16(32)
                .uint8(0)               // inline color-image part
                .int32(image.length)
                .bytes(image)
                .uint8(5)               // trailing "linear" marker, not image data
                .uint8(1).uint8(9)      // trailing filter byte
                .toByteArray();

        GuiSupport.Export exported = GuiSupport.export(new Layer("tex", payload));

        assertEquals("png", exported.ext);
        assertEquals("PNG texture", exported.desc);
        assertArrayEquals(image, exported.data);
    }

    @Test
    void tileExportReturnsEverythingAfterItsFourByteHeaderAsTheImage() {
        byte[] image = concat(GIF, ascii("terrain-tile-tail"));
        byte[] payload = new MessageWriter()
                .uint8('g')
                .uint8(0)
                .uint16(25)
                .bytes(image)
                .toByteArray();

        GuiSupport.Export exported = GuiSupport.export(new Layer("tile", payload));

        assertEquals("gif", exported.ext);
        assertEquals("GIF terrain tile", exported.desc);
        assertArrayEquals(image, exported.data);
    }

    @Test
    void audio2ExportStartsAtTheOggStream() {
        byte[] payload = new MessageWriter()
                .uint8(1)
                .string("sound/theme")
                .bytes(OGG)
                .toByteArray();

        GuiSupport.Export exported = GuiSupport.export(new Layer("audio2", payload));

        assertEquals("ogg", exported.ext);
        assertEquals("Ogg Vorbis audio", exported.desc);
        assertArrayEquals(OGG, exported.data);
    }

    @ParameterizedTest(name = "font/{0}")
    @MethodSource("fontFormats")
    void fontExportDropsTheHeaderAndKeepsTheFontProgram(String format, String expectedDescription,
                                                        byte[] signature) {
        byte[] program = concat(signature, ascii("font-program"));
        byte[] payload = new MessageWriter()
                .uint8(1)
                .uint8(0)
                .bytes(program)
                .toByteArray();

        GuiSupport.Export exported = GuiSupport.export(new Layer("font", payload));

        assertEquals(format, exported.ext);
        assertEquals(expectedDescription, exported.desc);
        assertArrayEquals(program, exported.data);
    }

    static Stream<Arguments> fontFormats() {
        return Stream.of(
                arguments("ttf", "TTF font", new byte[]{0x00, 0x01, 0x00, 0x00}),
                arguments("otf", "OTF font", ascii("OTTO")),
                arguments("ttc", "TTC font", ascii("ttcf"))
        );
    }

    @ParameterizedTest(name = "whole-layer-copy/{0}")
    @MethodSource("wholeLayerCopies")
    void midiAndTextLayersReturnAnIndependentCopyOfTheWholePayload(String name, String ext, String description) {
        byte[] payload = ascii("payload for " + name);

        GuiSupport.Export exported = GuiSupport.export(new Layer(name, payload));

        assertEquals(ext, exported.ext);
        assertEquals(description, exported.desc);
        assertArrayEquals(payload, exported.data);
        assertNotSame(payload, exported.data);
        exported.data[0] ^= 0x01;
        assertEquals('p', payload[0], "exported bytes must not alias the layer payload");
    }

    static Stream<Arguments> wholeLayerCopies() {
        return Stream.of(
                arguments("midi", "mid", "MIDI music"),
                arguments("tooltip", "txt", "Text"),
                arguments("pagina", "txt", "Text")
        );
    }

    @ParameterizedTest(name = "json/{0}")
    @MethodSource("jsonLayerFixtures")
    @SuppressWarnings("unchecked")
    void knownJsonLayersExportUtf8JsonAndKeepTheirCodecSpecificShape(String name, byte[] payload,
                                                                     String expectedRootKey) {
        GuiSupport.Export exported = GuiSupport.export(new Layer(name, payload));

        assertEquals("json", exported.ext);
        assertEquals("JSON", exported.desc);
        String json = new String(exported.data, StandardCharsets.UTF_8);
        Object parsed = Json.parse(json);
        assertTrue(parsed instanceof Map, "exported JSON should be an object for " + name);
        assertTrue(((Map<String, Object>) parsed).containsKey(expectedRootKey),
                () -> "JSON for " + name + " should contain '" + expectedRootKey + "': " + json);
        assertArrayEquals(json.getBytes(StandardCharsets.UTF_8), exported.data);
    }

    static Stream<Arguments> jsonLayerFixtures() {
        return Stream.of(
                arguments("props", new MessageWriter().uint8(1).toByteArray(), "props"),
                arguments("action", new MessageWriter()
                        .string("parent")
                        .uint16(2)
                        .string("Act")
                        .string("")
                        .uint16('A')
                        .uint16(1)
                        .string("arg")
                        .toByteArray(), "name"),
                arguments("mat2", new MessageWriter().uint16(3).toByteArray(), "id"),
                arguments("anim", new MessageWriter()
                        .int16(5)
                        .uint16(100)
                        .uint16(2)
                        .int16(1)
                        .int16(2)
                        .toByteArray(), "frames"),
                arguments("neg", new MessageWriter()
                        .int16(10).int16(20)
                        .int16(0).int16(0)
                        .int16(30).int16(40)
                        .int16(50).int16(60)
                        .uint8(1)
                        .uint8(7).uint16(1).int16(-5).int16(8)
                        .toByteArray(), "center"),
                arguments("obst", new MessageWriter()
                        .uint8(2)
                        .string("shape")
                        .uint8(1)
                        .uint8(2)
                        .float16(1.0f).float16(2.0f)
                        .float16(3.0f).float16(4.0f)
                        .toByteArray(), "polygons"),
                arguments("boneoff", new MessageWriter()
                        .string("hand")
                        .uint8(2).string("bone")
                        .uint8(4)
                        .toByteArray(), "name"),
                arguments("light", new MessageWriter()
                        .uint8(1)
                        .int16(7)
                        .float32(1.0f).float32(0.0f).float32(0.0f).float32(1.0f)
                        .float32(0.0f).float32(1.0f).float32(0.0f).float32(1.0f)
                        .float32(0.0f).float32(0.0f).float32(1.0f).float32(1.0f)
                        .toByteArray(), "ambient")
        );
    }

    @Test
    void codeExportReturnsTheCompiledClassBytesAfterTheClassName() {
        byte[] payload = new MessageWriter()
                .string("pkg.example.Sample")
                .bytes(CLASS_FILE)
                .toByteArray();

        GuiSupport.Export exported = GuiSupport.export(new Layer("code", payload));

        assertEquals("class", exported.ext);
        assertEquals("Java class file", exported.desc);
        assertArrayEquals(CLASS_FILE, exported.data);
    }

    @ParameterizedTest(name = "src/{0}")
    @MethodSource("sourceFiles")
    void srcExportUsesTheEmbeddedFileExtensionAndSourceBytes(String fileName, String expectedExt) {
        byte[] source = ascii("class " + fileName + " {}\n");
        byte[] payload = new MessageWriter()
                .uint8(1)
                .string(fileName)
                .bytes(source)
                .toByteArray();

        GuiSupport.Export exported = GuiSupport.export(new Layer("src", payload));

        assertEquals(expectedExt, exported.ext);
        assertEquals("Source file", exported.desc);
        assertArrayEquals(source, exported.data);
    }

    static Stream<Arguments> sourceFiles() {
        return Stream.of(
                arguments("Example.java", "java"),
                arguments("Widget.KT", "kt"),
                arguments("README", "java"),
                arguments("Trailing.", "java")
        );
    }

    @Test
    void depsExportProducesAReferenceListing() {
        byte[] payload = new MessageWriter()
                .uint8(1)
                .string("haven/res/lib/dependency")
                .uint16(3)
                .toByteArray();

        GuiSupport.Export exported = GuiSupport.export(new Layer("deps", payload));

        assertEquals("txt", exported.ext);
        assertEquals("Reference listing", exported.desc);
        String text = new String(exported.data, StandardCharsets.UTF_8);
        assertTrue(text.contains("Resource dependencies"));
        assertTrue(text.contains("haven/res/lib/dependency"));
        assertTrue(text.contains("@ v3"));
    }

    @Test
    void rlinkExportProducesAReferenceListing() {
        byte[] payload = new MessageWriter()
                .uint8(1) // old-style AmbientLink
                .string("haven/res/lib/ambient")
                .uint16(4)
                .toByteArray();

        GuiSupport.Export exported = GuiSupport.export(new Layer("rlink", payload));

        assertEquals("txt", exported.ext);
        assertEquals("Reference listing", exported.desc);
        String text = new String(exported.data, StandardCharsets.UTF_8);
        assertTrue(text.contains("Resource links"));
        assertTrue(text.contains("[ambient]"));
        assertTrue(text.contains("haven/res/lib/ambient"));
        assertTrue(text.contains("@ v4"));
    }

    @ParameterizedTest(name = "malformed-reference/{0}")
    @MethodSource("malformedReferenceLayers")
    void malformedDepsAndRlinkStillUseTheReferenceListingDescription(String name, String expectedText) {
        GuiSupport.Export exported = GuiSupport.export(new Layer(name, new byte[0]));

        assertEquals("txt", exported.ext);
        assertEquals("Reference listing", exported.desc);
        assertEquals(expectedText, new String(exported.data, StandardCharsets.UTF_8));
    }

    static Stream<Arguments> malformedReferenceLayers() {
        return Stream.of(
                arguments("deps", "(unrecognized deps layer)"),
                arguments("rlink", "(unrecognized rlink layer)")
        );
    }

    @Test
    void unknownLayerReturnsAnIndependentRawPayloadCopy() {
        byte[] payload = ascii("opaque-layer-data");

        GuiSupport.Export exported = GuiSupport.export(new Layer("not-a-known-layer", payload));

        assertEquals("bin", exported.ext);
        assertEquals("Raw bytes", exported.desc);
        assertArrayEquals(payload, exported.data);
        assertNotSame(payload, exported.data);
        exported.data[0] = 0;
        assertEquals('o', payload[0]);
    }

    @ParameterizedTest(name = "unexportable/{0}")
    @MethodSource("unexportablePayloads")
    void parsedButNonExportableLayersFallBackToRawBytes(String name, byte[] payload) {
        GuiSupport.Export exported = GuiSupport.export(new Layer(name, payload));

        assertEquals("bin", exported.ext);
        assertEquals("Raw bytes", exported.desc);
        assertArrayEquals(payload, exported.data);
        assertNotSame(payload, exported.data);
    }

    static Stream<Arguments> unexportablePayloads() {
        byte[] headerOnlyImage = imagePayload(ascii("not-an-image"));
        byte[] texWithoutMagic = new MessageWriter()
                .int16(1).uint16(0).uint16(0).uint16(8).uint16(8)
                .uint8(0).int32(4).bytes(ascii("nope"))
                .toByteArray();
        byte[] tileWithoutMagic = new MessageWriter()
                .uint8('b').uint8(1).uint16(2).bytes(ascii("nope"))
                .toByteArray();
        byte[] audioWithoutOgg = new MessageWriter()
                .uint8(1).string("sound").bytes(ascii("not-ogg"))
                .toByteArray();
        byte[] fontWithoutSfnt = new MessageWriter()
                .uint8(1).uint8(0).bytes(ascii("nope"))
                .toByteArray();

        return Stream.of(
                arguments("image", headerOnlyImage),
                arguments("tex", texWithoutMagic),
                arguments("tile", tileWithoutMagic),
                arguments("audio2", audioWithoutOgg),
                arguments("font", fontWithoutSfnt),
                arguments("code", new byte[]{0x41}),
                arguments("src", new byte[]{0x01})
        );
    }

    @ParameterizedTest(name = "json-fallback/{0}")
    @MethodSource("jsonCapableLayerNames")
    void nonLosslessJsonCandidatesFallBackToRawBytes(String name) {
        byte[] payload = new byte[]{0x7F}; // invalid/unsupported prefix for every typed codec

        GuiSupport.Export exported = GuiSupport.export(new Layer(name, payload));

        assertEquals("bin", exported.ext);
        assertEquals("Raw bytes", exported.desc);
        assertArrayEquals(payload, exported.data);
        assertNotSame(payload, exported.data);
    }

    static Stream<String> jsonCapableLayerNames() {
        return Stream.of("props", "action", "mat2", "anim", "neg", "obst", "boneoff", "light");
    }

    private static byte[] imagePayload(byte[] image) {
        return new MessageWriter()
                .uint8(1)       // legacy image header version
                .int8(0)        // z high byte (z = 1)
                .int16(0)       // sub-z
                .uint8(0)       // flags
                .int16(12)      // image id
                .int16(0)       // offset x
                .int16(0)       // offset y
                .bytes(image)
                .toByteArray();
    }

    private static byte[] ascii(String value) {
        return value.getBytes(StandardCharsets.UTF_8);
    }

    private static byte[] concat(byte[]... parts) {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        for(byte[] part : parts)
            out.writeBytes(part);
        return out.toByteArray();
    }
}
