@SuppressWarnings("unchecked")
void knownJsonLayersExportUtf8JsonAndKeepTheirCodecSpecificShape(String name, byte[] payload,
                                                                 String expectedRootKey,
                                                                 Object expectedRootValue) {
    GuiSupport.Export exported = GuiSupport.export(new Layer(name, payload));

    assertEquals("json", exported.ext);
    assertEquals("JSON", exported.desc);
    String json = new String(exported.data, StandardCharsets.UTF_8);
    Object parsed = Json.parse(json);
    assertTrue(parsed instanceof Map, "exported JSON should be an object for " + name);
    assertTrue(((Map<String, Object>) parsed).containsKey(expectedRootKey),
            () -> "JSON for " + name + " should contain '" + expectedRootKey + "': " + json);
    assertArrayEquals(json.getBytes(StandardCharsets.UTF_8), exported.data);
}

