            float[] local = M4.mul(M4.translate(b.px, b.py, b.pz),
                    M4.fromQuat(q[0], q[1], q[2], q[3]));
            if(b.parent.isEmpty()) {
                world.put(b.name, local);
                progress = true;
            } else if(world.containsKey(b.parent)) {
                world.put(b.name, M4.mul(world.get(b.parent), local));
                progress = true;
            }
        }
    }
    return world;
