        le(out, 0x46546C67);                                  // "glTF"
        le(out, 2);                                            // version
        le(out, total);
        le(out, jsonChunk.length);
        le(out, 0x4E4F534A);                                  // "JSON"
        out.writeBytes(jsonChunk);
        if(binChunk.length > 0) {
            le(out, binChunk.length);
            le(out, 0x004E4942);                              // "BIN\0"
