    private static double[] childDirection(List<SkelInfo.Bone> children) {
        if(children == null)
            return null;
        double[] sum = new double[3];
        for(SkelInfo.Bone child : children) {
            double length = Math.sqrt(child.px * child.px + child.py * child.py
                    + child.pz * child.pz);
            if(length > 1e-8) {
                sum[0] += child.px;
                sum[1] += child.py;
                sum[2] += child.pz;
