    static double[] nativeRotation(SkelInfo.Bone bone) {
        double half = bone.ang * 0.5;
        double sin = Math.sin(half);
        return normalizeQuat(new double[]{
                bone.ax * sin, bone.ay * sin, bone.az * sin, Math.cos(half)});
    }

    static double[] multiply(double[] a, double[] b) {
        return new double[]{
                a[3] * b[0] + a[0] * b[3] + a[1] * b[2] - a[2] * b[1],
                a[3] * b[1] - a[0] * b[2] + a[1] * b[3] + a[2] * b[0],
                a[3] * b[2] + a[0] * b[1] - a[1] * b[0] + a[2] * b[3],
                a[3] * b[3] - a[0] * b[0] - a[1] * b[1] - a[2] * b[2]};
    }

    static double[] conjugate(double[] q) {
        return new double[]{-q[0], -q[1], -q[2], q[3]};
    }

    static double[] rotate(double[] q, double[] value) {
        double[] result = multiply(multiply(q,
                new double[]{value[0], value[1], value[2], 0}), conjugate(q));
        return new double[]{result[0], result[1], result[2]};
    }

    private static double[] normalize(double[] value) {
        double length = Math.sqrt(value[0] * value[0] + value[1] * value[1]
