     *  {@link IllegalStateException} (the same type this skipper already throws for an
     *  unknown tag) instead of a {@link StackOverflowError}. Real tto data is shallow. */
    private static final int MAX_DEPTH = 256;

    private TtoSkip() {
    }

    /** Reads a type tag and skips its value. */
    public static void skipValue(MessageReader in) {
        skipTagged(in, in.uint8(), 1);
