                    } else if(pt == 1 || pt == 2 || pt == 3) {
                        in.skip(1);
                    } else if(pt == 5) {
                        /* no payload */
                    } else {
                        return t.found ? t : fail(t);
                    }
                } else if(fl == 1) {
                    in.skip(in.uint8());
                } else if(fl == 2) {
                    in.skip(1);
                    int n = in.int32();
                    if(n < 0 || (long) in.position() + n > data.length)
                        return t.found ? t : fail(t);
                    in.skip(n);
                } else {
                    return t.found ? t : fail(t);
                }
            }
        } catch(RuntimeException e) {
            return t.found ? t : fail(t);
        }
        return t;
    }

    private static TexInfo fail(TexInfo t) {
        t.found = false;
        t.lenFieldPos = -1;
        t.imageOffset = -1;
        t.imageLen = -1;
        return t;
    }
