    /** Builder for a version-1 vbuf2 payload (bare float32 attributes + optional bones). */
    private static final class Vbuf {
        private final int id;
        private final int num;
        private final List<String> names = new ArrayList<>();
        private final List<byte[]> payloads = new ArrayList<>();

        Vbuf(int id, int num) {
            this.id = id;
            this.num = num;
        }

        Vbuf attr(String name, float[] values) {
            MessageWriter w = new MessageWriter();
            for (float v : values)
                w.float32(v);
            names.add(name);
            payloads.add(w.toByteArray());
            return this;
        }

        /** One full-weight influence per vertex; names are in influence-index order. */
        Vbuf bones(String[] boneNames, int[] boneOfVertex) {
            if (boneOfVertex.length != num)
                throw new IllegalArgumentException("one bone per vertex expected");
            MessageWriter w = new MessageWriter();
            w.uint8(4);                                  // max bone amount
            for (int b = 0; b < boneNames.length; b++) {
                w.string(boneNames[b]);
                int v = 0;
                while (v < num) {
                    if (boneOfVertex[v] != b) {
                        v++;
                        continue;
                    }
                    int start = v;
                    while (v < num && boneOfVertex[v] == b)
                        v++;
                    w.uint16(v - start).uint16(start);
                    for (int k = start; k < v; k++)
                        w.float32(1f);
                }
                w.uint16(0);                             // end of runs for this bone
            }
            w.string("");                                // end of bone table
            names.add("bones");
            payloads.add(w.toByteArray());
            return this;
        }

        byte[] payload() {
            MessageWriter w = new MessageWriter();
            w.uint8(1).int16(id).uint16(num);
            for (int i = 0; i < names.size(); i++) {
                w.string(names.get(i));
                w.int32(payloads.get(i).length);
                w.bytes(payloads.get(i));
            }
            return w.toByteArray();
        }
    }

    /** Legacy FastMesh payload (vbufid present, raw index stream). */
    private static byte[] meshLegacy(int vbufid, int matid, int... indices) {
        MessageWriter w = new MessageWriter();
        w.uint8(16).uint16(indices.length / 3).int16(matid).int16(vbufid);
        for (int i : indices)
            w.uint16(i);
        return w.toByteArray();
    }

    /** Modern (tto metadata) FastMesh payload. */
    private static byte[] meshModern(int id, int vbufid, Integer matid, Integer ref, int... indices) {
        MessageWriter w = new MessageWriter();
        w.uint8(0x81).int16(id).int16(vbufid);
        if (matid != null)
            w.string("mat").uint8(10).int16(matid);     // tto INT16
        if (ref != null)
            w.string("ref").uint8(10).int16(ref);
        w.string("");                                   // end of metadata
        w.string("");                                   // fmt: raw index stream
        w.uint16(indices.length / 3);
        for (int i : indices)
            w.uint16(i);
        return w.toByteArray();
    }

    /** fmt-3 (half-float) manim with one contiguous run per frame. */
    private static byte[] manim(int id, float len, float[] times, int[][] verts, float[][][] deltas) {
        MessageWriter w = new MessageWriter();
        w.uint8(1).int16(id).uint8(0).float32(len);
        for (int f = 0; f < times.length; f++) {
            w.uint8(3).float32(times[f]).uint16(verts[f].length);
            w.uint16(verts[f][0]).uint16(verts[f].length);
            for (int k = 0; k < verts[f].length; k++) {
                w.float16(deltas[f][k][0]).float16(deltas[f][k][1]).float16(deltas[f][k][2]);
            }
        }
        w.uint8(0);
        return w.toByteArray();
    }

