    private static Glb glb(Result result) {
        byte[] raw = result.glb;
        assertNotNull(raw);
        assertTrue(raw.length >= 20, "GLB must contain the 12-byte header and a JSON chunk header");
        ByteBuffer b = ByteBuffer.wrap(raw).order(ByteOrder.LITTLE_ENDIAN);
        assertEquals(0x46546C67, b.getInt(0), "GLB magic");
        assertEquals(2, b.getInt(4), "GLB version");
        assertEquals(raw.length, b.getInt(8), "GLB total length");
        int jsonLen = b.getInt(12);
        assertEquals(0x4E4F534A, b.getInt(16), "JSON chunk type");
        assertEquals(0, jsonLen & 3, "JSON chunk must be 4-byte aligned");
        String json = new String(raw, 20, jsonLen, StandardCharsets.UTF_8);
        int pos = 20 + jsonLen;
        byte[] bin = new byte[0];
        if (pos < raw.length) {
            int binLen = b.getInt(pos);
            assertEquals(0x004E4942, b.getInt(pos + 4), "BIN chunk type");
            assertEquals(0, binLen & 3, "BIN chunk must be 4-byte aligned");
            bin = Arrays.copyOfRange(raw, pos + 8, pos + 8 + binLen);
        }
        return new Glb(map(Json.parse(json)), bin);
    }

    private static Map<String, Object> accessor(Glb g, Object index) {
        return map(list(g.json().get("accessors")).get(i(index)));
    }

    private static Map<String, Object> bufferView(Glb g, Object accessor) {
        Map<String, Object> acc = map(accessor);
        return map(list(g.json().get("bufferViews")).get(i(acc.get("bufferView"))));
    }

    private static float[] readFloats(Glb g, Object accIndex) {
        Map<String, Object> acc = accessor(g, accIndex);
        assertEquals(5126, i(acc.get("componentType")), "float accessor expected");
        int comps = switch (String.valueOf(acc.get("type"))) {
            case "SCALAR" -> 1;
            case "VEC2" -> 2;
            case "VEC3" -> 3;
            case "VEC4" -> 4;
            case "MAT4" -> 16;
            default -> throw new AssertionError("unexpected accessor type " + acc.get("type"));
        };
        int floats = i(acc.get("count")) * comps;
        Map<String, Object> bv = bufferView(g, acc);
        int off = i(bv.get("byteOffset"));
        ByteBuffer bin = ByteBuffer.wrap(g.bin()).order(ByteOrder.LITTLE_ENDIAN);
        float[] out = new float[floats];
        for (int k = 0; k < floats; k++)
            out[k] = bin.getFloat(off + 4 * k);
        return out;
    }

    private static int[] readU16(Glb g, Object accIndex) {
        Map<String, Object> acc = accessor(g, accIndex);
        assertEquals(5123, i(acc.get("componentType")), "ushort accessor expected");
        Map<String, Object> bv = bufferView(g, acc);
        int off = i(bv.get("byteOffset"));
        ByteBuffer bin = ByteBuffer.wrap(g.bin()).order(ByteOrder.LITTLE_ENDIAN);
        int[] out = new int[i(acc.get("count"))];
        for (int k = 0; k < out.length; k++)
            out[k] = bin.getShort(off + 2 * k) & 0xffff;
        return out;
    }

    private static void assertVec(Object value, double... expected) {
        List<Object> actual = list(value);
        assertEquals(expected.length, actual.size(), "vector length");
        for (int k = 0; k < expected.length; k++)
            assertEquals(expected[k], d(actual.get(k)), 1e-5, "component " + k);
    }

