package resforge.model;

import org.junit.jupiter.api.Test;
import resforge.io.Json;
import resforge.io.MessageWriter;
import resforge.layers.Mat2Codec;
import resforge.layers.MeshInfo;
import resforge.layers.SkanInfo;
import resforge.layers.SkelInfo;
import resforge.res.Layer;
import resforge.res.ResContainer;

import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

/** Behavioural tests for the composite glTF/GLB exporter entry point. */
class GltfExportToGlbTests {

    /* --------------------------------------------------------------- fixtures */

    private static Layer layer(String name, byte[] data) {
        return new Layer(name, data);
    }

    private static ResContainer res(Layer... layers) {
        ResContainer r = new ResContainer(7);
        for (Layer l : layers)
            r.layers.add(l);
        return r;
    }

    private static byte[] attr(float[] vals) {
        MessageWriter w = new MessageWriter();
        for (float v : vals)
            w.float32(v);
        return w.toByteArray();
    }

    /** Version-1 vbuf2 layer with bare float32 attributes and optional skinning. */
    private static byte[] vbuf(int id, int num, float[] pos, float[] nrm, float[] tex,
                               String[] boneNames, int[] bonePerVertex) {
        Map<String, byte[]> attrs = new LinkedHashMap<>();
        if (pos != null) attrs.put("pos", attr(pos));
        if (nrm != null) attrs.put("nrm", attr(nrm));
        if (tex != null) attrs.put("tex", attr(tex));
        if (boneNames != null) attrs.put("bones", bones(num, boneNames, bonePerVertex));
        MessageWriter w = new MessageWriter();
        w.uint8(1).int16(id).uint16(num);
        for (Map.Entry<String, byte[]> e : attrs.entrySet())
            w.string(e.getKey()).int32(e.getValue().length).bytes(e.getValue());
        return w.toByteArray();
    }

    private static byte[] bones(int num, String[] names, int[] bonePerVertex) {
        MessageWriter w = new MessageWriter();
        w.uint8(4);
        for (int b = 0; b < names.length; b++) {
            w.string(names[b]);
            int v = 0;
            while (v < num) {
                if (bonePerVertex[v] != b) {
                    v++;
                    continue;
                }
                int start = v;
                while (v < num && bonePerVertex[v] == b) v++;
                w.uint16(v - start).uint16(start);
                for (int i = start; i < v; i++) w.float32(1f);
            }
            w.uint16(0);
        }
        w.string("");
        return w.toByteArray();
    }

    private static byte[] legacyMesh(int vbufid, int matid, int... indices) {
        assert indices.length % 3 == 0;
        MessageWriter w = new MessageWriter();
        w.uint8(16).uint16(indices.length / 3).int16(matid).int16(vbufid);
        for (int i : indices) w.uint16(i);
        return w.toByteArray();
    }

    private static byte[] modernMesh(int id, int vbufid, Integer matid, int... indices) {
        assert indices.length % 3 == 0;
        MessageWriter w = new MessageWriter();
        w.uint8(0x81).int16(id).int16(vbufid);
        if (matid != null) w.string("mat").uint8(10).int16(matid);
        w.string("");                       // end of tto metadata
        w.string("");                       // raw (not strip) index format
        w.uint16(indices.length / 3);
        for (int i : indices) w.uint16(i);
        return w.toByteArray();
    }

    /** fmt-3 (float16) manim layer. */
    private static byte[] manim(int id, float len, float[] times, int[][] verts, float[][][] deltas) {
        MessageWriter w = new MessageWriter();
        w.uint8(1).int16(id).uint8(0).float32(len);
        for (int f = 0; f < times.length; f++) {
            w.uint8(3).float32(times[f]).uint16(verts[f].length);
            int i = 0;
            while (i < verts[f].length) {
                int start = verts[f][i], j = i + 1;
                while (j < verts[f].length && verts[f][j] == verts[f][j - 1] + 1) j++;
                w.uint16(start).uint16(j - i);
                for (int k = i; k < j; k++)
                    w.float16(deltas[f][k][0]).float16(deltas[f][k][1]).float16(deltas[f][k][2]);
                i = j;
            }
        }
        w.uint8(0);
        return w.toByteArray();
    }

    private static byte[] skeleton(SkelInfo.Bone... bones) {
        return SkelInfo.encodeVer1(Arrays.asList(bones));
    }

    private static SkelInfo.Bone bone(String name, String parent, float px, float py, float pz) {
        return new SkelInfo.Bone(name, parent, px, py, pz, 0, 0, 1, 0);
    }

    private static byte[] skan(int id, float len, String mode, SkanInfo.Track... tracks) {
        SkanInfo s = new SkanInfo();
        s.id = id;
        s.fmt = 0;
        s.mode = mode;
        s.len = len;
        s.tracks.addAll(Arrays.asList(tracks));
        return SkanInfo.encode(s);
    }

    private static SkanInfo.Track track(String boneName, float[] times) {
        float[][] trans = new float[times.length][];
        float[][] rot = new float[times.length][];
        for (int i = 0; i < times.length; i++) {
            trans[i] = new float[]{i * 0.25f, 0, 0};
            rot[i] = new float[]{1, 0, 0, 0};
        }
        return new SkanInfo.Track(boneName, times.clone(), trans, rot);
    }

    private static byte[] tex(int id, String format, byte[] image) {
        MessageWriter w = new MessageWriter();
        w.int16(id).uint16(0).uint16(0).uint16(16).uint16(16);
        w.uint8(0).int32(image.length).bytes(image);
        return w.toByteArray();
    }

    private static byte[] png() {
        return new byte[]{(byte) 0x89, 'P', 'N', 'G', 0x0D, 0x0A, 0x1A, 0x0A, 1, 2, 3};
    }

    private static byte[] jpeg() {
        return new byte[]{(byte) 0xFF, (byte) 0xD8, (byte) 0xFF, 9, 8, 7};
    }

    private static byte[] mat2(int id, String key, int texId) {
        Map<String, Object> model = new LinkedHashMap<>();
        model.put("id", (long) id);
        model.put("entries", List.of(Map.of("key", key,
                "values", List.of(Map.of("u16", (long) texId)))));
        return Mat2Codec.encode(model);
    }

    /* ------------------------------------------------------------ glb helpers */

    private record Glb(Map<String, Object> json, byte[] bin) {
    }

    private static Glb glb(byte[] bytes) {
        ByteBuffer b = ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN);
        assertEquals(0x46546C67, b.getInt(0), "glTF magic");
        assertEquals(2, b.getInt(4), "glTF version");
        assertEquals(bytes.length, b.getInt(8), "declared total length");
        int jsonLen = b.getInt(12);
        assertEquals(0x4E4F534A, b.getInt(16), "JSON chunk type");
        assertEquals(0, jsonLen % 4, "JSON chunk must be 4-byte aligned");
        Object parsed = Json.parse(new String(bytes, 20, jsonLen, StandardCharsets.UTF_8));
        int pos = 20 + jsonLen;
        byte[] bin = new byte[0];
        if (pos < bytes.length) {
            int binLen = b.getInt(pos);
            assertEquals(0x004E4942, b.getInt(pos + 4), "BIN chunk type");
            assertEquals(0, binLen % 4, "BIN chunk must be 4-byte aligned");
            bin = Arrays.copyOfRange(bytes, pos + 8, pos + 8 + binLen);
        }
        return new Glb(map(parsed), bin);
    }

    @SuppressWarnings("unchecked")
    private static Map<String, Object> map(Object o) {
        return (Map<String, Object>) o;
    }

    @SuppressWarnings("unchecked")
    private static List<Object> list(Object o) {
        return (List<Object>) o;
    }

    private static int i(Object o) {
        return ((Number) o).intValue();
    }

    private static Map<String, Object> at(Map<String, Object> m, Object index) {
        return map(list(m.get("materials")).get(i(index)));
    }

    private static Map<String, Object> accessor(Glb g, Object idx) {
        return map(list(g.json.get("accessors")).get(i(idx)));
    }

    private static Map<String, Object> viewOf(Glb g, Object accessorIdx) {
        Map<String, Object> acc = accessor(g, accessorIdx);
        return map(list(g.json.get("bufferViews")).get(i(acc.get("bufferView"))));
    }

    private static float[] floats(Glb g, Object accessorIdx) {
        Map<String, Object> acc = accessor(g, accessorIdx);
        Map<String, Object> bv = viewOf(g, accessorIdx);
        int typeSize = switch (String.valueOf(acc.get("type"))) {
            case "SCALAR" -> 1;
            case "VEC2" -> 2;
            case "VEC3" -> 3;
            case "VEC4" -> 4;
            case "MAT4" -> 16;
            default -> fail("unexpected accessor type " + acc.get("type"));
        };
        int n = i(acc.get("count")) * typeSize;
        ByteBuffer b = ByteBuffer.wrap(g.bin).order(ByteOrder.LITTLE_ENDIAN);
        int off = i(bv.get("byteOffset"));
        float[] out = new float[n];
        for (int k = 0; k < n; k++) out[k] = b.getFloat(off + k * 4);
        return out;
    }

    private static int[] ushorts(Glb g, Object accessorIdx) {
        Map<String, Object> acc = accessor(g, accessorIdx);
        Map<String, Object> bv = viewOf(g, accessorIdx);
        int n = i(acc.get("count"));
        ByteBuffer b = ByteBuffer.wrap(g.bin).order(ByteOrder.LITTLE_ENDIAN);
        int off = i(bv.get("byteOffset"));
        int[] out = new int[n];
        for (int k = 0; k < n; k++) out[k] = b.getShort(off + k * 2) & 0xffff;
        return out;
    }

    private static byte[] viewBytes(Glb g, Object accessorIdx) {
        Map<String, Object> bv = viewOf(g, accessorIdx);
        int off = i(bv.get("byteOffset")), len = i(bv.get("byteLength"));
        return Arrays.copyOfRange(g.bin, off, off + len);
    }

    private static void vec(Object actual, double... expected) {
        List<Object> l = list(actual);
        assertEquals(expected.length, l.size(), "vector length");
        for (int k = 0; k < expected.length; k++)
            assertEquals(expected[k], ((Number) l.get(k)).doubleValue(), 1e-5, "component " + k);
    }

    private static Map<String, Object> primitive(Glb g, int idx) {
        return map(list(map(list(g.json.get("meshes")).get(0)).get("primitives")).get(idx));
    }

