    @Test
    void manimLayersBecomeMorphTargetsAndWeightAnimation() {
        ResContainer model = res(
                layer("vbuf2", vbuf(1, 2, new float[]{0, 0, 0, 1, 0, 0}, null, null, null, null)),
                layer("mesh", legacyMesh(1, 0, 0, 1, 1)),
                layer("manim", manim(3, 1f, new float[]{0f, 0.5f},
                        new int[][]{{0}, {0, 1}},
                        new float[][][]{{{0, 1, 0}}, {{0, 1, 0}, {0, 0, 2}}})));

        GltfExport.Result r = GltfExport.toGlb(model, model, model, "plant.res");
        Glb g = glb(r.glb);
        Map<String, Object> meshObj = map(list(g.json.get("meshes")).get(0));
        assertEquals(List.of(0.0, 0.0), list(meshObj.get("weights")));

        Map<String, Object> p = primitive(g, 0);
        List<Object> targets = list(p.get("targets"));
        assertEquals(2, targets.size());
        assertFalse(map(targets.get(0)).isEmpty());
        assertFalse(map(targets.get(1)).isEmpty());

        Map<String, Object> t0 = accessor(g, map(targets.get(0)).get("POSITION"));
        vec(t0.get("min"), 0, 0, -1);
        vec(t0.get("max"), 0, 0, -1);
        assertArrayEquals(new float[]{0, 0, -1, 0, 0, 0},
                floats(g, map(targets.get(0)).get("POSITION")), 1e-6);

        Map<String, Object> t1 = accessor(g, map(targets.get(1)).get("POSITION"));
        vec(t1.get("min"), 0, 0, -1);
        vec(t1.get("max"), 0, 2, 0);
        assertArrayEquals(new float[]{0, 0, -1, 0, 2, 0},
                floats(g, map(targets.get(1)).get("POSITION")), 1e-6);

        List<Object> animations = list(g.json.get("animations"));
        assertEquals(1, animations.size());
        Map<String, Object> a = map(animations.get(0));
        assertEquals("morph_0", a.get("name"));
        Map<String, Object> channel = map(list(a.get("channels")).get(0));
        assertEquals(0, i(map(channel.get("target")).get("node")));
        assertEquals("weights", map(channel.get("target")).get("path"));
        Map<String, Object> sampler = map(list(a.get("samplers")).get(0));
        assertEquals("LINEAR", sampler.get("interpolation"));
        assertArrayEquals(new float[]{0f, 0.5f, 1f}, floats(g, sampler.get("input")), 1e-6);
        Map<String, Object> out = accessor(g, sampler.get("output"));
        assertEquals("SCALAR", out.get("type"));
        assertEquals(6, i(out.get("count")));
        assertArrayEquals(new float[]{1, 0, 0, 1, 1, 0},
                floats(g, sampler.get("output")), 1e-6, "last key loops back to frame 0");
    }

