        assertEquals(0x46546C67, b.getInt(0), "glTF magic");
        assertEquals(2, b.getInt(4), "glTF version");
        assertEquals(bytes.length, b.getInt(8), "declared total length");
        int jsonLen = b.getInt(12);
        assertEquals(0x4E4F534A, b.getInt(16), "JSON chunk type");
        assertEquals(0, jsonLen % 4, "JSON chunk must be 4-byte aligned");
        Object parsed = Json.parse(new String(bytes, 20, jsonLen, StandardCharsets.UTF_8));
        int pos = 20 + jsonLen;
        byte[] bin = new byte[0];
        if (pos < bytes.length) {
            int binLen = b.getInt(pos);
            assertEquals(0x004E4942, b.getInt(pos + 4), "BIN chunk type");
            assertEquals(0, binLen % 4, "BIN chunk must be 4-byte aligned");
            bin = Arrays.copyOfRange(bytes, pos + 8, pos + 8 + binLen);
