            "bit", 3,
            "otex", 2);

    private Vbuf2Format() {
    }

    /** Elements per vertex for a bare or {@code 2}-formatted attribute, or -1. */
    public static int elements(String attributeName) {
        String base = attributeName.endsWith("2")
                ? attributeName.substring(0, attributeName.length() - 1)
