    /** Parses the matid out of a "rfmat_<int>" material name (tolerating Blender's ".001" suffixes). */
    private static Integer parseMatid(String name) {
        if(name == null)
            return null;
        int p = name.indexOf("rfmat_");
        if(p < 0)
            return null;
        int i = p + 6;
        int start = i;
        if(i < name.length() && name.charAt(i) == '-') i++;
        while(i < name.length() && Character.isDigit(name.charAt(i))) i++;
        if(i == start || (i == start + 1 && name.charAt(start) == '-'))
            return null;
        try {
            return Integer.parseInt(name.substring(start, i));
        } catch(NumberFormatException e) {
            return null;
        }
    }

    /** Parses the original mesh-layer ordinal from "rfmat_<matid>_mesh_<index>". */
    private static Integer parseMeshIndex(String name) {
        if(name == null)
            return null;
        int p = name.indexOf("_mesh_");
        if(p < 0)
            return null;
        int start = p + 6, end = start;
        while(end < name.length() && Character.isDigit(name.charAt(end)))
            end++;
        if(end == start)
            return null;
        try {
            return Integer.parseInt(name.substring(start, end));
        } catch(NumberFormatException e) {
            return null;
        }
    }

