        }
        float[] raw = readAccessor(g, ((Number) idxAcc).intValue(), 1);
        if(raw.length % 3 != 0)
            throw new IllegalArgumentException("primitive has " + raw.length
                    + " indices, not a multiple of 3 (not a triangle list)");
