        for(int i = 0; i < raw.length; i++) {
            int v = Math.round(raw[i]);
            if(v < 0 || v >= pc)
                throw new IllegalArgumentException("triangle index " + v + " out of range [0, " + pc + ")");
            tris[i] = v;
        }
        return tris;
    }

