            if(res.layers.get(i).name.equals("skel")) {
                skelIdx = i;
                break;
            }
        if(skelIdx < 0)
            return null;
        SkelInfo si = SkelInfo.parse(res.layers.get(skelIdx).data);
        if(!si.recognized || si.bones.isEmpty())
            return null;
        List<Object> nodes = (List<Object>) root.get("nodes");
        List<Object> skins = (List<Object>) root.get("skins");
        if(nodes == null || skins == null || skins.isEmpty())
            return null;
        Map<String, Object> skin = skinUsedByMesh(root);
        List<Object> jointValues = (List<Object>) skin.get("joints");
        if(jointValues == null || jointValues.isEmpty())
            return null;
        Map<Integer, Integer> parentByNode = new HashMap<>();
        for(int parent = 0; parent < nodes.size(); parent++) {
            List<Object> children = (List<Object>) ((Map<String, Object>) nodes.get(parent))
                    .get("children");
            if(children == null)
                continue;
            for(Object value : children) {
                int child = idx(value);
                if(child < 0 || child >= nodes.size())
                    throw new IllegalArgumentException("skeleton child node is out of range: " + child);
                Integer previous = parentByNode.putIfAbsent(child, parent);
                if(previous != null && previous != parent)
                    throw new IllegalArgumentException("skeleton node has multiple parents");
            }
        }

        LinkedHashSet<Integer> jointNodes = new LinkedHashSet<>();
        Map<String, Integer> nodeByName = new LinkedHashMap<>();
        for(Object value : jointValues) {
            int index = idx(value);
            if(index < 0 || index >= nodes.size())
                throw new IllegalArgumentException("skin joint node is out of range: " + index);
            Map<String, Object> node = (Map<String, Object>) nodes.get(index);
            Object nameValue = node.get("name");
            if(isSkeletonBasisMarker(nameValue))
                continue;
            if(!(nameValue instanceof String) || ((String) nameValue).isEmpty())
                throw new IllegalArgumentException("a skeleton joint has no bone name");
            String name = (String) nameValue;
            if(nodeByName.putIfAbsent(name, index) != null)
                throw new IllegalArgumentException("multiple skeleton joints are named " + name);
            jointNodes.add(index);
        }
        if(jointNodes.isEmpty())
            return null;
        Map<String, InverseBindLocal> inverseBindLocals = hasPrettySkeletonBasis(root)
                ? Map.of() : inverseBindLocalTransforms(g);

        Map<String, SkelInfo.Bone> originalByName = new LinkedHashMap<>();
        for(SkelInfo.Bone bone : si.bones)
            originalByName.put(bone.name, bone);
