                ? BoneBasis.forSkeleton(si) : Map.of();
        Map<String, double[]> importBases = new HashMap<>(exportBases);
        for(String name : nodeByName.keySet())
            importBases.putIfAbsent(name, new double[]{0, 0, 0, 1});

        List<String> order = new ArrayList<>();
        for(SkelInfo.Bone bone : si.bones)
            if(nodeByName.containsKey(bone.name))
                order.add(bone.name);
        for(String name : nodeByName.keySet())
            if(!originalByName.containsKey(name))
                order.add(name);

        List<SkelInfo.Bone> out = new ArrayList<>();
        for(String name : order) {
            int index = nodeByName.get(name);
            String parentName = nearestJointParent(index, parentByNode, jointNodes,
                    nodes, null);
            Map<String, Object> node = (Map<String, Object>) nodes.get(index);
            double[] xf;
            InverseBindLocal inverseBind = inverseBindLocals.get(name);
            if(inverseBind != null) {
