                        MessageReader sub = new MessageReader(payload, at, sublen);
                        d.attribs.put(name, decodeAttr(sub, name, d.num));
                    } else if(name.equals("bones") || name.equals("bones2")) {
                        MessageReader sub = new MessageReader(payload, at, sublen);
                        parseBones(d, sub, name.equals("bones2"), d.num);
