                }
                if(name.equals("bones") || name.equals("bones2")) {
                    parseBones(d, in, name.equals("bones2"), d.num);
                    continue;
                }
                int eln = Vbuf2Format.elements(name);
                if(eln < 0)
                    break;
                d.attribs.put(name, decodeAttr(in, name, d.num));
