        if(name.endsWith("2")) {
            in.uint8();                 // data version (== 1)
            String fmt = in.string();
            readFmt(in, fmt, dst);
        } else {
            for(int i = 0; i < dst.length; i++)
                dst[i] = in.float32();  // bare float32 (loadbuf)
        }
        return dst;
    }

