            case "uvec1": { float F = 1.0f / 127.0f;
                for(int i = 0; i < cap; ) {
                    oct2uvec(vb, in.int8() * F, in.int8() * F);
                    dst[i++] = vb[0]; dst[i++] = vb[1]; dst[i++] = vb[2];
