                break; }
            case "uvec2": { float F = 1.0f / 32767.0f;
                for(int i = 0; i < cap; ) {
                    oct2uvec(vb, in.int16() * F, in.int16() * F);
                    dst[i++] = vb[0]; dst[i++] = vb[1]; dst[i++] = vb[2];
