                j4[v * 4 + k] = ba[base + order[k]];
                w4[v * 4 + k] = (tw != 0) ? bw[base + order[k]] / tw : 0;
            }
            if(keep == 0) {             // unweighted vertex: bind fully to the first bone
                j4[v * 4] = 0;
                w4[v * 4] = 1;
