    @Test
    void tangentsAreRecomputedAndWrittenToBothTanAndBit() {
        byte[] orig = res(
                new Layer("vbuf2", vbuf(0, 0, 3,
                        bare("pos", 0, 0, 0, 1, 0, 0, 0, 0, 1),
                        bare("nrm", 0, 0, 1, 0, 0, 1, 0, 0, 1),
                        bare("tex", 0, 0, 1, 0, 0, 1),
                        bare("tan", 0, 0, 0, 0, 0, 0, 0, 0, 0),
                        bare("bit", 0, 0, 0, 0, 0, 0, 0, 0, 0))),
                new Layer("mesh", mesh(1, 0, 0, 1, 2)));

        GltfBuilder g = new GltfBuilder();
        int pos = g.addFloatAccessor(new float[]{0, 0, 0, 1, 0, 0, 0, 1, 0}, 3);
        int nrm = g.addFloatAccessor(new float[]{0, 0, 1, 0, 0, 1, 0, 0, 1}, 3);
        int tex = g.addFloatAccessor(new float[]{0, 0, 1, 0, 0, 1}, 2);
        int idx = g.addShortIndices(new int[]{0, 1, 2});
        byte[] glb = g.build(meshJson(primitive(
                        "POSITION", pos, "NORMAL", nrm, "TEXCOORD_0", tex, idx, null)),
                SINGLE_NODE, SINGLE_SCENE, null);

        RebuildResult result = GltfImport.rebuild(orig, glb);

        Vbuf2Codec out = Vbuf2Codec.parse(ResContainer.parse(result.res).layers.get(0).data);
        float[] tan = out.decodeAttr("tan");
        float[] bit = out.decodeAttr("bit");
        float[] normals = out.decodeAttr("nrm");
        assertNotNull(tan);
        assertArrayEquals(tan, bit, "Haven stores bit identically to tan");
        for(int v = 0; v < result.vertices; v++) {
            float len = (float) Math.sqrt(tan[v * 3] * tan[v * 3]
                    + tan[v * 3 + 1] * tan[v * 3 + 1]
                    + tan[v * 3 + 2] * tan[v * 3 + 2]);
            assertEquals(1f, len, 1e-5f, "recomputed tangents must be normalised");
            float dot = tan[v * 3] * normals[v * 3]
                    + tan[v * 3 + 1] * normals[v * 3 + 1]
                    + tan[v * 3 + 2] * normals[v * 3 + 2];
            assertEquals(0f, dot, 1e-5f, "tangents are orthogonalised against the normal");
        }
        assertTrue(tan[0] > 0.9f, "the UV gradient should produce a +X tangent here");
    }

