    @Test
    void morphFramesAreReencodedAtTheNewVertexCountFromGlbTargets() {
        byte[] orig = res(
                new Layer("vbuf2", vbuf(0, 0, 3, bare("pos", 0, 0, 0, 1, 0, 0, 0, 1, 0))),
                new Layer("mesh", mesh(1, 0, 0, 1, 2)),
                new Layer("manim", manim(4, 1.25f, 2, new int[]{0, 1}, new float[][]{
                        {1, 0, 0}, {0, 1, 0}}, new float[]{0f, 0.5f})));

        GltfBuilder g = new GltfBuilder();
        int pos = g.addFloatAccessor(new float[]{0, 0, 0, 1, 0, 0, 0, 1, 0}, 3);
        int target0 = g.addFloatAccessor(new float[]{1, 0, 0,
                0, 0, 0,
                0, 0, 0}, 3);
        int target1 = g.addFloatAccessor(new float[]{0, 0, 0,
                0, 1, 0,
                0, 0, 0}, 3);
        int idx = g.addShortIndices(new int[]{0, 1, 2});
        String prim = "{\"attributes\":{\"POSITION\":" + pos + "},\"indices\":" + idx
                + ",\"targets\":[{\"POSITION\":" + target0 + "},{\"POSITION\":" + target1 + "}]}";
        byte[] glb = g.build(meshJson(prim), SINGLE_NODE, SINGLE_SCENE, null);

        RebuildResult result = GltfImport.rebuild(orig, glb);

        assertEquals(2, result.triangles);
        List<Layer> out = ResContainer.parse(result.res).layers;
        assertEquals(List.of("vbuf2", "mesh", "manim"), layerNames(out));
        MeshAnimInfo manim = MeshAnimInfo.parse(out.get(2).data);
        assertTrue(manim.recognized);
        assertEquals(2, manim.frames.size());
        assertEquals(0f, manim.frames.get(0).time, 1e-6f, "frame timing must be preserved");
        assertEquals(0.5f, manim.frames.get(1).time, 1e-6f, "frame timing must be preserved");

        MeshAnimInfo.Frame f0 = manim.frames.get(0);
        assertEquals(1, f0.vertices);
        assertEquals(0, f0.idx[0]);
        assertArrayEquals(new float[]{1, 0, 0}, f0.pos, 1e-6f);

        MeshAnimInfo.Frame f1 = manim.frames.get(1);
        assertEquals(1, f1.vertices);
        assertEquals(1, f1.idx[0]);
        assertArrayEquals(new float[]{0, 0, 1}, f1.pos, 1e-6f,
                "morph deltas are axis-inverted into Haven space");
    }

