    }

    private static Attr formatted(String name, String fmt, float... values) {
        MessageWriter w = new MessageWriter();
        w.uint8(1).string(fmt);
        if(!fmt.equals("f4"))
            throw new IllegalArgumentException("test helper only writes f4");
        for(float v : values)
