    /** A {@code bones2} attribute with one bone receiving the same weight for every vertex. */
    private static Attr bones2(int num, String bone, float... weights) {
        MessageWriter w = new MessageWriter();
        w.uint8(1).string("f4").uint8(weights.length == 0 ? 1 : weights.length / Math.max(1, num));
        w.string(bone);
        w.uint16(num).uint16(0);
        for(float weight : weights)
            w.float32(weight);
        w.uint16(0).uint16(0);
        w.string("");
        return new Attr("bones2", w.toByteArray());
    }

    private static byte[] vbuf(int ver, int id, int num, Attr... attrs) {
        MessageWriter w = new MessageWriter();
        w.uint8(ver);
        if(ver >= 1)
            w.int16(id);
        w.uint16(num);
        for(Attr attr : attrs) {
            w.string(attr.name);
            if(ver >= 1)
                w.int32(attr.data.length);
            w.bytes(attr.data);
        }
        return w.toByteArray();
    }

    /** FastMesh "old" form with a vbufid and raw uint16 triangle indices. */
    private static byte[] mesh(int matid, int vbufid, int... tris) {
        MessageWriter w = new MessageWriter();
        w.uint8(16).uint16(tris.length / 3).int16(matid).int16(vbufid);
        for(int t : tris)
            w.uint16(t);
        return w.toByteArray();
    }

    /** One fmt-3 manim frame per supplied delta; each frame animates one vertex. */
    private static byte[] manim(int id, float length, int frameCount, int[] vertices,
                                float[][] deltas, float[] times) {
        MessageWriter w = new MessageWriter();
        w.uint8(1).int16(id).uint8(0).float32(length);
        for(int f = 0; f < frameCount; f++) {
            w.uint8(3).float32(times[f]).uint16(1);
            w.uint16(vertices[f]).uint16(1);
            w.float16(deltas[f][0]).float16(deltas[f][1]).float16(deltas[f][2]);
        }
        w.uint8(0);
        return w.toByteArray();
    }

