        w.string("col2").int32(attrs.get("col2").length).bytes(attrs.get("col2"));
        byte[] orig = res(
                layer("vbuf2", w.toByteArray()),
                layer("mesh", oldMesh(1, 0, 0, 1, 2)));
        Glb g = new Glb();
