package resforge.model;

import org.junit.jupiter.api.Test;
import resforge.io.MessageWriter;
import resforge.layers.MeshAnimInfo;
import resforge.layers.MeshInfo;
import resforge.res.Layer;
import resforge.res.ResContainer;
import resforge.vbuf.Vbuf2Codec;
import resforge.model.Vbuf2Data;

import java.io.ByteArrayOutputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

/** Behavioural tests for {@link GltfImport#rebuild(byte[], byte[])}. */
class GltfImportRebuildTests {

    /* ------------------------------------------------------------------ helpers */

    private static byte[] res(Layer... layers) {
        ResContainer c = new ResContainer(1);
        for (Layer l : layers) c.layers.add(l);
        return c.serialize();
    }

    private static Layer layer(String name, byte[] data) {
        return new Layer(name, data);
    }

    /** A ver-0 vbuf2 with one or more bare float32 attributes. */
    private static byte[] bareVbuf(int num, Object... nameAndValues) {
        MessageWriter w = new MessageWriter();
        w.uint8(0).uint16(num);
        for (int i = 0; i < nameAndValues.length; i += 2) {
            w.string((String) nameAndValues[i]);
            float[] vals = (float[]) nameAndValues[i + 1];
            for (float v : vals) w.float32(v);
        }
        return w.toByteArray();
    }

    /** A ver-1 vbuf2 with formatted attributes (attribute name -> sub-buffer bytes). */
    private static byte[] formattedVbuf(int id, int num, Map<String, byte[]> attrs) {
        MessageWriter w = new MessageWriter();
        w.uint8(1).int16(id).uint16(num);
        for (Map.Entry<String, byte[]> e : attrs.entrySet()) {
            w.string(e.getKey()).int32(e.getValue().length).bytes(e.getValue());
        }
        return w.toByteArray();
    }

    private static byte[] f4(float... vals) {
        MessageWriter w = new MessageWriter();
        w.uint8(1).string("f4");
        for (float v : vals) w.float32(v);
        return w.toByteArray();
    }

    /** bones2 sub-buffer: every vertex fully weighted to the single bone "root". */
    private static byte[] bones2SingleRoot(int num) {
        MessageWriter w = new MessageWriter();
        w.uint8(1).string("f4").uint8(1);      // data version, weight format, max influences
        w.string("root");
        w.uint16(num).uint16(0);               // run count, first vertex
        for (int i = 0; i < num; i++) w.float32(1f);
        w.uint16(0).uint16(0);                 // end of this bone's spans
        w.string("");                          // end of bone list
        return w.toByteArray();
    }

    /** A manim layer with fmt-3 frames, each moving one vertex by a half-float delta. */
    private static byte[] manim(float len, float[] times, int[] vertices, float[][] deltas) {
        MessageWriter w = new MessageWriter();
        w.uint8(1).int16(3).uint8(0).float32(len);
        for (int i = 0; i < times.length; i++) {
            w.uint8(3).float32(times[i]).uint16(1);
            w.uint16(vertices[i]).uint16(1);
            w.float16(deltas[i][0]).float16(deltas[i][1]).float16(deltas[i][2]);
        }
        w.uint8(0);
        return w.toByteArray();
    }

    /** Old-form FastMesh: flags=16 (vbufid present), uint16 tri count, int16 matid, int16 vbufid, indices. */
    private static byte[] oldMesh(int matid, int vbufid, int... tris) {
        MessageWriter w = new MessageWriter();
        w.uint8(16).uint16(tris.length / 3).int16(matid).int16(vbufid);
        for (int t : tris) w.uint16(t);
        return w.toByteArray();
    }

    private static ResContainer roundTrip(byte[] raw) {
        return ResContainer.parse(raw);
    }

    private static Layer layerNamed(ResContainer c, String name) {
        for (Layer l : c.layers) if (l.name.equals(name)) return l;
        fail("no layer named " + name + " in " + names(c));
        return null;
    }

    private static List<Layer> layersNamed(ResContainer c, String name) {
        List<Layer> out = new ArrayList<>();
        for (Layer l : c.layers) if (l.name.equals(name)) out.add(l);
        return out;
    }

    private static List<String> names(ResContainer c) {
        List<String> n = new ArrayList<>();
        for (Layer l : c.layers) n.add(l.name);
        return n;
    }

    private static byte[] utf8(String s) {
        return s.getBytes(StandardCharsets.UTF_8);
    }

    /* --------------------------------------------------------------- GLB builder */

    private static final class Glb {
        private final ByteArrayOutputStream bin = new ByteArrayOutputStream();
        private final StringBuilder accessors = new StringBuilder();
        private final StringBuilder views = new StringBuilder();
        private final StringBuilder materials = new StringBuilder();
        private int accessorCount, viewCount, materialCount;

        int material(String name) {
            if (materialCount > 0) materials.append(',');
            materials.append("{\"name\":\"").append(name).append("\"}");
            return materialCount++;
        }

        private int addView(byte[] data) {
            while (bin.size() % 4 != 0) bin.write(0);
            int off = bin.size();
            bin.writeBytes(data, 0, data.length);
            if (viewCount > 0) views.append(',');
            views.append("{\"buffer\":0,\"byteOffset\":").append(off)
                    .append(",\"byteLength\":").append(data.length).append('}');
            return viewCount++;
        }

        private int addAccessor(String json) {
            if (accessorCount > 0) accessors.append(',');
            accessors.append(json);
            return accessorCount++;
        }

        private static String type(int comps) {
            return switch (comps) {
                case 1 -> "SCALAR";
                case 2 -> "VEC2";
                case 3 -> "VEC3";
                default -> "VEC4";
            };
        }

        int floats(float[] data, int comps) {
            MessageWriter w = new MessageWriter();
            for (float v : data) w.float32(v);
            int v = addView(w.toByteArray());
            return addAccessor("{\"bufferView\":" + v + ",\"componentType\":5126,\"count\":"
                    + (data.length / comps) + ",\"type\":\"" + type(comps) + "\"}");
        }

        /** All-zero accessor: no bufferView is legal and keeps huge counts cheap. */
        int zeroFloats(int count, int comps) {
            return addAccessor("{\"componentType\":5126,\"count\":" + count
                    + ",\"type\":\"" + type(comps) + "\"}");
        }

        int ushorts(int[] data) {
            MessageWriter w = new MessageWriter();
            for (int v : data) w.uint16(v);
            int v = addView(w.toByteArray());
            return addAccessor("{\"bufferView\":" + v + ",\"componentType\":5123,\"count\":"
                    + data.length + ",\"type\":\"SCALAR\"}");
        }

        int ubytes4(int[] data) {
            MessageWriter w = new MessageWriter();
            for (int v : data) w.uint8(v);
            int v = addView(w.toByteArray());
            return addAccessor("{\"bufferView\":" + v + ",\"componentType\":5121,\"count\":"
                    + (data.length / 4) + ",\"type\":\"VEC4\"}");
        }

        byte[] build(String meshes, String nodes) {
            return build(meshes, nodes, "{\"nodes\":[0]}", null);
        }

        byte[] build(String meshes, String nodes, String scenes, String skins) {
            StringBuilder json = new StringBuilder("{");
            json.append("\"asset\":{\"version\":\"2.0\"},");
            json.append("\"accessors\":[").append(accessors).append("],");
            json.append("\"bufferViews\":[").append(views).append("],");
            if (materialCount > 0) json.append("\"materials\":[").append(materials).append("],");
            json.append("\"buffers\":[{\"byteLength\":").append(bin.size()).append("}],");
            json.append("\"meshes\":").append(meshes).append(',');
            json.append("\"nodes\":").append(nodes).append(',');
            json.append("\"scenes\":").append(scenes).append(',');
            json.append("\"scene\":0");
            if (skins != null) json.append(",\"skins\":").append(skins);
            json.append('}');

            byte[] jsonBytes = utf8(json.toString());
            int jsonPadded = (jsonBytes.length + 3) & ~3;
            byte[] binBytes = bin.toByteArray();
            int binPadded = (binBytes.length + 3) & ~3;
            int total = 12 + 8 + jsonPadded + 8 + binPadded;
            java.nio.ByteBuffer bb = java.nio.ByteBuffer.allocate(total)
                    .order(java.nio.ByteOrder.LITTLE_ENDIAN);
