    @Test
    void tangentAndBitAreRecomputedIdentically() {
        Map<String, byte[]> attrs = new LinkedHashMap<>();
        attrs.put("pos", new byte[36]);
        attrs.put("nrm", new byte[36]);
        attrs.put("tex", new byte[24]);
        attrs.put("tan", f4(1, 0, 0, 1, 0, 0, 1, 0, 0));
        attrs.put("bit", f4(1, 0, 0, 1, 0, 0, 1, 0, 0));
        MessageWriter w = new MessageWriter();
        w.uint8(0).uint16(3).string("pos");
        for (int i = 0; i < 9; i++) w.float32(0);
        w.string("nrm");
        for (int i = 0; i < 9; i++) w.float32(0);
        w.string("tex");
        for (int i = 0; i < 6; i++) w.float32(0);
        for (String name : List.of("tan", "bit")) {
            w.string(name).int32(attrs.get(name).length).bytes(attrs.get(name));
        }
        byte[] orig = res(
                layer("vbuf2", w.toByteArray()),
                layer("mesh", oldMesh(1, 0, 0, 1, 2)));
        Glb g = new Glb();
        int pos = g.floats(new float[]{0, 0, 0, 1, 0, 0, 0, 1, 0}, 3);
        int nrm = g.floats(new float[]{0, 0, 1, 0, 0, 1, 0, 0, 1}, 3);
        int tex = g.floats(new float[]{0, 0, 1, 0, 0, 1}, 2);
        int idx = g.ushorts(new int[]{0, 1, 2});
        byte[] glb = g.build(
                "[{\"primitives\":[{\"attributes\":{\"POSITION\":" + pos + ",\"NORMAL\":" + nrm
                        + ",\"TEXCOORD_0\":" + tex + "},\"indices\":" + idx + "}]}]",
                "[{\"mesh\":0}]");

        GltfImport.RebuildResult r = GltfImport.rebuild(orig, glb);

        Vbuf2Codec vbuf = Vbuf2Codec.parse(layerNamed(roundTrip(r.res), "vbuf2").data);
        float[] tan = vbuf.decodeAttr("tan");
        float[] bit = vbuf.decodeAttr("bit");
        assertNotNull(tan);
        assertNotNull(bit);
        assertArrayEquals(tan, bit, 1e-6f);
        float[] n = vbuf.decodeAttr("nrm");
        for (int v = 0; v < 3; v++) {
            double len = Math.sqrt(tan[v * 3] * tan[v * 3] + tan[v * 3 + 1] * tan[v * 3 + 1]
                    + tan[v * 3 + 2] * tan[v * 3 + 2]);
            assertEquals(1.0, len, 1e-5);
            double dot = tan[v * 3] * n[v * 3] + tan[v * 3 + 1] * n[v * 3 + 1]
                    + tan[v * 3 + 2] * n[v * 3 + 2];
            assertEquals(0.0, dot, 1e-5);
        }
    }

